-- Generated init script for local PostgreSQL (all text columns)

DO $$ BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticator LOGIN PASSWORD 'postgrest' NOINHERIT; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
GRANT anon TO authenticator;

CREATE TABLE usuarios (
  id bigint generated by default as identity primary key,
  usuario text,
  contrasena text,
  rol integer
);

CREATE TABLE autorizados (
  id bigint generated by default as identity primary key,
  nombre text
);

CREATE TABLE status (
  id bigint generated by default as identity primary key,
  status text
);

CREATE TABLE tipo (
  id bigint generated by default as identity primary key,
  tipo text
);

CREATE TABLE recibida (
  id bigint generated by default as identity primary key,
  Fecha_Recibido text,
  Remite text,
  Asunto text,
  Recibio text,
  fecha_evento text,
  HORA text,
  "PDF-Imagen" text,
  Lugar text,
  TELEFONO text,
  CORREO text
);

CREATE TABLE despachada (
  id bigint generated by default as identity primary key,
  "Fecha" text,
  Elaboro text,
  Dirigido text,
  Asunto text,
  Estatus text,
  "Recibió" text,
  "Fecha_recepcion" text,
  "Archivos y multimedia" text,
  TELEFONO text,
  CORREO text
);

CREATE TABLE iniciativas (
  id bigint generated by default as identity primary key,
  no integer,
  fecha_oficio text,
  fecha_presentacion_oficialia text,
  texto text,
  comision text,
  fecha_turno_legis text,
  fecha_pleno text,
  dictaminada_favor_contra text,
  decreto text,
  pdf text,
  objeto text,
  opinion_consultoria text,
  proyecto_dictamen text,
  proyecto_decreto text
);

CREATE TABLE proposiciones (
  id bigint generated by default as identity primary key,
  no integer,
  fecha_ingreso_procepar text,
  fecha_pleno text,
  proposicion text,
  resultado_votacion text,
  fecha_acuse_recibido_autoridad text,
  fecha_respuesta_autoridad text,
  anotaciones text,
  tipo text,
  pdf_foto text,
  acuerdo text,
  respuesta_acuerdo text,
  objetivo text,
  turnado_comision text
);

CREATE TABLE fisca (
  id bigint generated by default as identity primary key,
  ano text,
  fecha_sesion text,
  dictamen_no text,
  dependencia text,
  observaciones text,
  dictamen text,
  voto_diputada text,
  fallo text,
  created_at text,
  voto_final text
);








SEGUNDO: A LA GOBERNADORA DEL ESTADO, MAESTRA MARINA DEL PILAR ÁVILA OLMENDA, Y A LA PRESIDENTA MUNICIPAL DE MEXICALI, BAJA CALIFORNIA, MAESTRA NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE, EN COORDINACIÓN CON LAS DEPENDENCIAS COMPETENTES, DESTINEN LOS RECURSOS NECESARIOS PARA CUBRIR EL COMPLEMENTO DE $1,050 PESOS POR TONELADA, Y ASÍ SE ALCANCE EL PRECIO DE $7,050 PESOS POR TONELADA, QUE GARANTICE LA RENTABILIDAD MÍNIMA DEL CULTIVO.', 'RETIRADA', '19/5/2025', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICION PRECIO TRIGO.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/sKLzmht4Cnqt?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=df4be90ce4c5ab7b2b22840b598b42ceeb67fa522f854036ee006e57c2d12b87&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICION%2520PRECIO%2520TRIGO.pdf&x-id=GetObject', 'ACUERDO AGRICULTURA PRECIO OBJETIVO Y DISPERSIÓN.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/cp9O9TlJS5E4?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=a0f3974b2705091cc0297e2f9c3ace61b52cbc1837db2e534e2f34f57881e790&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520AGRICULTURA%2520PRECIO%2520OBJETIVO%2520Y%2520DISPERSI%25C3%2593N.pdf&x-id=GetObject', 'NULL', 'ASIGNACION DE 300 PRECIO TONELADA TRIGO CRISTALINO Y QUE SE CUBRA EL COMPLEMENTO DE 1,050 POR TONELADA Y SE ALCANCE EL PRECIO OBJETIVO 7,050.', 'NULL');

SEGUNDO. SE EXHORTA DE MANERA URGENTE Y RESPETUOSA A LA PRESIDENTA MUNICIPAL DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE, EN UN PLAZO NO MAYOR A 30 DÍAS NATURALES, PRESENTE ANTE LA CIUDADANÍA Y ESTA SOBERANÍA, UN PLAN INTEGRAL DE REHABILITACIÓN DE LOS ESPACIOS DENOMINADOS UNIDADES DEPORTIVAS Y CENTROS PILARES, PRIORIZANDO ZONAS CON MAYOR REZAGO SOCIAL, ALTA INCIDENCIA DELICTIVA O CONCENTRACIÓN JUVENIL, Y EN DICHO PLAN, EXTERIORICE SI UTILIZARA PARTIDAS PRESUPUESTALES, INDICANDO LOS MONTOS Y LOS NOMBRES DE LAS PERSONAS QUE SERÁN LOS RESPONSABLES DESIGNADOS. 

TERCERO. SE EXHORTA AL SÍNDICO PROCURADOR DEL XXV AYUNTAMIENTO DE MEXICALI JOSÉ OSCAR VEGA MARÍN, ASÍ COMO AL AUDITOR SUPERIOR DEL ESTADO DE BAJA CALIFORNIA ARNULFO RAÚL ZARATE CHÁVEZ, PARA QUE AMPLÍEN LAS AUDITORÍAS YA INICIADAS SOBRE EL USO DE RECURSOS PÚBLICOS EN BIENESTAR SOCIAL MUNICIPAL (BISOM), A BIEN QUE LOS RESULTADOS OBTENIDOS DE DICHAS AUDITORIAS, SE TURNEN LOS HALLAZGOS A LA FISCALÍA GENERAL DEL ESTADO, EN CASO DE DETECTAR IRREGULARIDADES QUE CONFIGUREN RESPONSABILIDADES PENALES Y/O ADMINISTRATIVAS.”', 'NO APROBADA', 'NULL', 'NULL', 'SE TURNÓ A LA COMISIÓN DE FORTALECIMIENTO MUNICIPAL', 'PROPOSICION', 'MYGM PROPOSICIÓN UNIDADES DEPORTIVAS YC PILARES BISOM.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/9HjDaPkmqeH2?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=3d62a81284767b6e2f6cd608080a2b6f7e3559771b77c2a5b61d6ad41f943b2f&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520UNIDADES%2520DEPORTIVAS%2520YC%2520PILARES%2520BISOM.pdf&x-id=GetObject', 'CR TURNESE PROPOSICION A COM DE FORTALECIMIENTO MUNICIPAL.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/nk4iahkNY2Mm?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=2b95ae56e25ca8f6cf131517edca035e5e0fbbae4f4dc08dea1bd2c7df5e7a5b&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27CR%2520TURNESE%2520PROPOSICION%2520A%2520COM%2520DE%2520FORTALECIMIENTO%2520MUNICIPAL.pdf&x-id=GetObject,CR OPINIÓN CL PROPOSICION UNIDADES DEPORTIVAS Y PILARES A CARGO DE BISOM.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/RthofElyc9a7?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=9ea634bbedcfe6f9c299d475e61483593ec90c65a830607e30d716b3f956977a&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27CR%2520OPINI%25C3%2593N%2520CL%2520PROPOSICION%2520UNIDADES%2520DEPORTIVAS%2520Y%2520PILARES%2520A%2520CARGO%2520DE%2520BISOM.pdf&x-id=GetObject', 'NULL', 'SE REALICE EVALUACIÓN TÉCNICA, PLAN DE REHABILITACIÓN Y AMPLIACIÓN DE AUDITORIAS POR LA AUDITORIA SUPERIOR A LAS UNIDADES DEPORTIVAS Y CENTROS PILARES RESPONSABILIDAD DE BISOM.', 'NULL');

SEGUNDO: POR LO ANTERIOR, RESULTA IMPERANTE QUE LA SECRETARÍA GENERAL DE GOBIERNO, POR MEDIO DE LA DIRECCIÓN ESTATAL DEL REGISTRO CIVIL, REFUERCE LOS PROCESOS DE CAPACITACIÓN, SUPERVISIÓN Y CONTROL DE CALIDAD EN LA ELABORACIÓN DE EXTRACTOS DE ACTAS, ASÍ COMO LA IMPLEMENTACIÓN DE PROTOCOLOS EFICIENTES PARA LA ATENCIÓN Y RESOLUCIÓN INMEDIATA DE ERRORES, PRIORIZANDO EL INTERÉS SUPERIOR DE LA PERSONA Y LA PROTECCIÓN EFECTIVA DE SUS DERECHOS.', 'APROBADA', '18/7/2025', '12/8/2025', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN ACTAS DE NACIMIENTO .pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/EGzhXBMfs63e?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=a074d30b193b9332640f6ad8328d3ed81de14a9db097c9d18ee843bdd356375d&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520ACTAS%2520DE%2520NACIMIENTO%2520.pdf&x-id=GetObject', 'NULL', 'RE AL REGISTRO CIVIL RELATIVO A ACTAS DE NACIMIENTO.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/0caog4MsBbGB?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205454Z&X-Amz-Expires=518400&X-Amz-Signature=cbdcf3a4795978bfddea5111226c632e6aef1b80769f4f9a447acea5457d770f&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27RE%2520AL%2520REGISTRO%2520CIVIL%2520RELATIVO%2520A%2520ACTAS%2520DE%2520NACIMIENTO.pdf&x-id=GetObject', 'QUE SE ELABOREN CON MAYOR PROBIDAD Y CUIDADO EL EXTRACTO DE ACTAS EN EL REGISTRO CIVIL Y QUE ATIENDAN CON PRONTITUD LA CORRECCIÓN DE ERRORES EXISTENTES CONFORME A LA INFORMACIÓN PLASMADA EN LA COPIA FIEL DEL LIBRO DEL ACTA QUE SE TRATE', 'NULL');
PRIMERO: CUÁLES SON LOS PROYECTOS, OBRAS O PRODUCTOS QUE ACTUALMENTE SE ENCUENTRAN COMPROMETIDOS O EN EJECUCIÓN DE CONSTRUCCIÓN, AMPLIACIÓN O HABILITACIÓN DE NUEVOS PLANTELES DE EDUCACIÓN MEDIA SUPERIOR EN EL ESTADO. 
SEGUNDO: CUÁL ES EL PRESUPUESTO AUTORIZADO Y ASIGNADO PARA FINES DE CONSTRUCCIÓN, AMPLIACIÓN O HABILITACIÓN DE NUEVOS PLANTELES DE EDUCACIÓN MEDIA SUPERIOR EN EL ESTADO, PARA LO CUAL DEBERÁ DETALLAR FUENTE DE FINANCIAMIENTO, DISTRIBUCIÓN POR MUNICIPIO Y CALENDARIO DE SU EJERCICIO. 
TERCERO: QUÉ PROGRAMAS, MECANISMOS O HERRAMIENTAS EXISTEN ACTUALMENTE PARA AMPLIAR LA CAPACIDAD DE ATENCIÓN Y REGISTRO DE INSCRIPCIÓN DE NUEVO INGRESO Y CONTINUIDAD DE ESTUDIOS, EN LAS ESCUELAS PÚBLICAS DE EDUCACIÓN MEDIA SUPERIOR. 
CUARTO: QUÉ ESQUEMAS DE BECAS ESTATALES, SUBSIDIOS O CONVENIOS SE TIENEN CONTEMPLADOS DE MANERA ESPECÍFICA CON INSTITUCIONES DE EDUCACIÓN PRIVADAS, CON EL FIN DE GARANTIZAR QUE NINGÚN JOVEN EN BAJA CALIFORNIA QUEDE FUERA DEL SISTEMA EDUCATIVO POR FALTA DE ESPACIO. 
QUINTO: QUE SE REALICE LA RUTA ESPECIFICA CON LA CUAL SE PUEDA DESTINAR DEL PRÓXIMO PRESUPUESTO DE EGRESOS DEL ESTADO DE BAJA CALIFORNIA, ESPECÍFICAMENTE DEL QUE SE AUTORICE POR ESTA SOBERANÍA PARA EL 2026 Y EN DELANTE, PARTIDA SUFICIENTE PARA A CONSTRUCCIÓN DE INSTITUCIONES ESCOLARES Y PARTIDA ESPECÍFICA PARA LA ENTREGA DE BECAS PARA ESTUDIAR EN ESCUELAS PARTICULARES POR NO EXISTIR INFRAESTRUCTURA ESCOLAR DE GOBIERNO".', 'APROBADA', '21/8/2025', 'NULL', 'NULL', 'PROPOSICION', 'PROPOSICIÓN ESPACIOS PREPARATORIAS.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/kwRfZ76JDXfn?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=df4da18313fd4b59a778831955b7fd915f5d826bcaba0c30ce8e7005b77ac6c4&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27PROPOSICI%25C3%2593N%2520ESPACIOS%2520PREPARATORIAS.pdf&x-id=GetObject', 'ACUERDO MPAO PLANTELES MEDIA SUP.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/XnXSL7cBjeLV?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=397d8beb54ca0c1c7402c154caefe7474ae212fe121c22eb3bb7c20360a8c8a2&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520MPAO%2520PLANTELES%2520MEDIA%2520SUP.pdf&x-id=GetObject', 'NULL', 'CONOCER LOS PROYECTOS DE OBRA DE PLANTELES DE EDUCACIÓN MEDIA SUPERIOR, EL PRESUPUESTO AUTORIZADO, MECANISMOS PARA AUMENTAR EL NUEVO INGRESO, ESQUEMAS DE ATENCIÓN CON INSTITUCIONES PRIVADAS PARA ABATIR EL REZAGO, PROGRAMACION DE PRESUPUESTO PARA BECAS EN INSTITUCIONES PRIVADAS.', 'NULL');
SEGUNDO: El H. Congreso del Estado de Baja California, exhorta respetuosamente a la Secretaria de Medio Ambiente y Desarrollo Sustentable de Baja California, Mónica Juliana Vega Aguirre; a efecto que realice acciones de vigilancia y control de emisión de contaminantes y control de fauna nociva, que emana de los drenes que se encuentran dentro de la mancha urbana, de manera importante al este de esta Ciudad; 
TERCERO: El H. Congreso del Estado de Baja California, exhorta respetuosamente a la Presidenta Municipal de Mexicali, Norma Alicia Bustamante Martínez;  para que dentro de sus atribuciones, dicte instrucciones al Director de Protección al Ambiente del XXV Ayuntamiento de Mexicali, Tomás Alberto Hernández Ruiz; al Director de Servicios Públicos Municipales del XXV Ayuntamiento de Mexicali, Juan Francisco Garza Ceseña; para que realicen acciones de vigilancia, limpieza y control de emisión de contaminantes y control de fauna nociva, que emana de los drenes que se encuentran dentro de la mancha urbana, de manera importante al este de esta Ciudad; así también para que coloquen señalización urbana en la que se indique disminución de velocidad y precaución en la periferia y cercanía de estos drenes al este de la Ciudad, lo anterior para seguridad de la población; 
CUARTO: El H. Congreso del Estado de Baja California, exhorta respetuosamente al Director de Seguridad Pública Municipal del XXV Ayuntamiento de Mexicali, Luis Felipe Chan Baltazar, a efecto de que el personal a su cargo realice rondines frecuentes y sorpresivos, con la intención de infraccionar y de ser necesario, detener en flagrancia a quienes pretendan realizar actos de contaminación a los drenes que se encuentran dentro de la mancha urbana, de manera importante al este de esta Ciudad.”', 'APROBADA', '4/9/2025', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN LIMPIEZA DRENES 25082025.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/gfr0tPw7W6Ie?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=a53298a38c81890134244b8f07c4d23bb530992085b732d7aa0b48ca23f28dd1&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520LIMPIEZA%2520DRENES%252025082025.pdf&x-id=GetObject', 'ACUERDO CONAGUA SMADS AYMTO MXLI DSPM PROPOSICIÓN DRENES.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/c9BzkSksq3Pr?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=f0d38096a44ebcf65ed84bfa4115ddf3a4b9f61ebf4e5844803a8a98664abb58&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520CONAGUA%2520SMADS%2520AYMTO%2520MXLI%2520DSPM%2520PROPOSICI%25C3%2593N%2520DRENES.pdf&x-id=GetObject', 'NULL', 'ATENCIÓN Y LIMPIEZA DE DRENES POR PARTE DE CONAGUA, SRIA. DEL MEDIO AMBIENTE Y AYUNTAMIENTO DE MEXICALI.', 'NULL');
UNO. DISEÑEN Y PRESENTEN LOS EXHORTADOS, UN PLAN INTEGRAL DE ATENCIÓN A LA COLONIA SATURNO Y SUS ZONAS COLINDANTES, CON ACCIONES CONCRETAS, PRESUPUESTO ASIGNADO Y PLAZOS DEFINIDOS PARA PAVIMENTACIÓN, REPARACIÓN VIAL, ALUMBRADO PÚBLICO, SEGURIDAD, SEMAFORIZACIÓN Y SEÑALIZACIÓN VIAL, INCLUYENDO NOMENCLATURA.
DOS. RINDAN LOS EXHORTADOS, UN INFORME PÚBLICO EN UN PLAZO NO MAYOR A TREINTA DÍAS ANTE ESTE CONGRESO SOBRE EL ESTADO ACTUAL DE LA INFRAESTRUCTURA VIAL, EL NÚMERO DE CALLES SIN PAVIMENTAR, LUMINARIAS FUERA DE SERVICIO Y SEMÁFOROS INOPERANTES EN DICHA ZONA.
TRES. ATIENDAN DE INMEDIATO LOS EXHORTADOS, LOS PUNTOS DE MAYOR URGENCIA, PRIORIZANDO LAS CALLES MÁS AFECTADAS Y LAS ZONAS DONDE EL RIESGO SANITARIO Y DE INSEGURIDAD SEA MÁS ALTO.
