INSERT INTO iniciativas (id, no, fecha_oficio, fecha_presentacion_oficialia, texto, comision, fecha_turno_legis, fecha_pleno, dictaminada_favor_contra, decreto, pdf, objeto, opinion_consultoria, proyecto_dictamen, proyecto_decreto) VALUES ('53', 0, '', '2025-11-04', 'CON PROYECTO DE DECRETO, MEDIANTE EL CUAL SE DEROGAN Y REFORMAN DIVERSAS DISPOSICIONES DE LA LEY ORGÁNICA DE LA FISCALÍA GENERAL DEL ESTADO DE BAJA CALIFORNIA Y DE LA LEY DEL SISTEMA ESTATAL DE SEGURIDAD CIUDADANA DE BAJA CALIFORNIA, A FIN DE REASIGNAR LA ADSCRIPCIÓN DEL CENTRO DE CONTROL, COMANDO, COMUNICACIÓN, CÓMPUTO, CALIDAD Y CONTACTO CIUDADANO (C5), A LA SECRETARÍA DE SEGURIDAD CIUDADANA', 'COMISIÓN DE GOBERNACIÓN, LEGISLACIÓN Y PUNTOS CONSTITUCIONALES', '', '', 'NULL', 'NULL', '["NULL","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1787958469148-4r2vy8xugfm.pdf"]', 'REASIGNAR LA ADSCRIPCIÓN DEL CENTRO DE CONTROL, COMANDO, COMUNICACIÓN, CÓMPUTO, CALIDAD Y CONTACTO CIUDADANAO (C5) A LA SECRETARÍA DE SEGURIDAD CIUDADANA', NULL, NULL, NULL);
INSERT INTO iniciativas (id, no, fecha_oficio, fecha_presentacion_oficialia, texto, comision, fecha_turno_legis, fecha_pleno, dictaminada_favor_contra, decreto, pdf, objeto, opinion_consultoria, proyecto_dictamen, proyecto_decreto) VALUES ('3', 6, '', '2025-02-25', 'CON PROYECTO DE DECRETO POR EL QUE SE ADICIONA LA FRACCIÓN VI AL ARTÍCULO 49, SE REFROMA EL ARTÍCULO 62 Y SE CREA EL ARTÍCULO 65 DE LA LEY DE LOS DERECHOS, PROTECCIÓN E INTEGRACIÓN DE LAS PERSONAS ADULTAS MAYORES EN EL ESTADO DE BAJA CALIFORNIA.', 'DERECHOS HUMANOS', '2024-12-19', '2025-09-11', 'NULL', 'NULL', '["NULL","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1787610571412-fabflgrqwx5.pdf"]', 'QUE SE INVESTIGUEN DE OFICIO, POR LA COMISIÓN ESTATAL DE DERECHOS HUMANOS, LAS QUEJAS QUE SE PRSENTEN SOBRE VIOLACIONES A LOS DERECHOS FUNDAMENTALES DE LAS PERSONAS ADULTAS MAYORES', NULL, '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1787610573409-g6l3p0iwt.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1787610573409-xkbpnb90huj.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1787610578961-1exkgn91ek4.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1787960356991-7k6ovgdl8pq.pdf"]');
INSERT INTO iniciativas (id, no, fecha_oficio, fecha_presentacion_oficialia, texto, comision, fecha_turno_legis, fecha_pleno, dictaminada_favor_contra, decreto, pdf, objeto, opinion_consultoria, proyecto_dictamen, proyecto_decreto) VALUES ('84', NULL, '2026-09-07', '2026-09-07', 'CON PROYECTO DE DECRETO POR EL QUE SE REFORMA EL ARTÍCULO 75 DE LA LEY DE EDUCACIÓN DEL ESTADO DE BAJA CALIFORNIA.', '', '', '', '', '', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/iniciativas/1788898882746-zkih14ge92p.pdf"]', 'REGULAR EL USO DE DISPOSITIVOS ELECTRÓNICOS EN LOS PLANTELES EDUCATIVOS DE EDUCACIÓN BÁSICA Y MEDIA SUPERIOR', NULL, NULL, NULL);
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('1', 1, '5/11/2024', '10/11/2024', 'PROPOSICIÓN CON PUNTO DE ACUERDO; ÚNICO: EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA, MTRA. MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE, A TRAVÉS DE SU SECRETARIO DE SALUD, DR. JOSÉ ADRIÁN MEDINA AMARILLAS, A EFECTO DE QUE SE IMPLEMENTE LA INSTALACIÓN DE UN MURO DE CONTENCIÓN EN LOS CORDONES PERIMETRALES PARA EVITAR ACCIDENTES, LA DESIGNACIÓN DE GUARDIAS DE SEGUIDAD EN TURNOS QUE ABARQUEN LAS VEINTICUATRO HORAS, CON EL FIN DE PROTEGER A LOS FAMILIARES QUE ESPERAN EN LAS CALLES Y DE MANERA IMPORTANTE LA DISPOSICIÓN DE ALGÚN LUGAR O ZONA SEGURA QUE FUNCIONE DE SALA DE ESPERA CON LA FINALIDAD DE QUE UN FAMILIAR DE CUALQUIER PACIENTE GRAVE QUE SE ENCUENTRE ATENDIDO Y HOSPITALIZADO EN EL DENOMINADO HOSPITAL GENERAL MEXICALI, DEPENDIENTE DE LA SECRETARÍA DE SALUD PUEDA ESPERAR DE MANERA SEGURA Y NO BAJO EL INCLEMENTE ESTADO DEL TIEMPO DE NUESTRA LOCALIDAD, INFORMACIÓN RELATIVA AL ESTADO DE SALUD DE SU FAMILIAR ATENDIDO EN ESTE NOSOCOMIO.', 'APROBADA', '11/10/2024', '11/12/2024', 'NULL', 'PROPOSICION', 'NULL', 'NULL', 'NULL', 'IMPLEMENTE LA INSTALACIÓN DE UN MURO DE CONTENCIÓN EN LOS CORDONES PERIMETRALES PARA EVITAR ACCIDENTES, LA DESIGNACIÓN DE GUARDIAS DE SEGUIDAD EN TURNOS QUE ABARQUEN LAS VEINTICUATRO HORAS, CON EL FIN DE PROTEGER A LOS FAMILIARES QUE ESPERAN EN LAS CALLES', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('2', 2, '18/10/2024', '21/10/2024', 'PROPOSICIÓN CON PUNTO DE ACUERDO; ÚNICO: EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA, MTRA. MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE, A TRAVÉS DE SU SECRETARIO DE SALUD, DR. JOSÉ ADRIÁN MEDINA AMARILLAS, INFORME LAS POLÍTICAS PÚBLICAS A IMPLEMENTAR A EFECTO DE PROMOVER Y FACILITAR LA LACTANCA MATERNA EN ESPACIOS PÚBLICOS A TRAVÉS DE LA INSTALACIÓN Y/O CONSTRUCCIÓN EN TODO EL ESTADO DE SALAS DE LACTANCIA EN LAZAS COMERCIALES, PARQUES, EDIFICIOS PÚBLICOS, ENTRE OTROS.', 'APROBADA', '29/10/2024', '11/12/2024', 'NULL', 'PROPOSICION', 'MYGM PROPOSICION SALAS DE LACTANCIA.docx https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/OzgqzEcaiJ6s?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=4ba539b42e786f2c6dd423ba3f834ab0bb50c3545449f370706f65919c0eca78&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICION%2520SALAS%2520DE%2520LACTANCIA.docx&x-id=GetObject', 'ACUERDO SALAS DE LACTANCIA ESPACIOS PÚBLICOS .pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/GgMqUZ0rIXmF?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=660af0eb6346891c008d7d841422d0cb79d052787d81ccd8bbda99040972bfa1&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520SALAS%2520DE%2520LACTANCIA%2520ESPACIOS%2520P%25C3%259ABLICOS%2520.pdf&x-id=GetObject', 'NULL', 'INFORME LAS POLÍTICAS PÚBLICAS A IMPLEMENTAR A EFECTO DE PROMOVER Y FACILITAR LA LACTANCA MATERNA EN ESPACIOS PÚBLICOS A TRAVÉS DE LA INSTALACIÓN Y/O CONSTRUCCIÓN EN TODO EL ESTADO DE SALAS DE LACTANCIA EN LAZAS COMERCIALES, PARQUES, EDIFICIOS PÚBLICOS, ENTRE OTROS.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('3', 3, '7/10/2024', '10/10/2024', 'PROPOSICIÓN CON PUNTO DE ACUERDO; ÚNICO: EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA PRESIDENTA MUNICIPAL DEL 25 AYUNTAMIENTO DE MEXICALI, BAJA CALIFRONIA, MTRA NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE EN COORDINACIÓN CON LAS AUTORIDADES QUE CORRESPONDAN, REALICEN LAS ACCIONES Y GESTIONES NECESARIAS TENDIENTES A LOGRAR LA IMPLEMENTACIÓN DE UN PROGRAMA QUE PERMITA OPTIMIZAR Y SINCRONIZAR EL FUNCIONAMIENTO DE LOS SEMÁFOROS EN LAS VÍAS DE CIRCULACIÓN MÁS IMPORTANTE DE MEXICALI, COMO SON: EN TODA SU LONGITUD, BOULEVAR ADOLFO LÓPEZ MATEOS, BOULEVAR BENITO JÚAREZ Y SU CONTINUACIÓN DENOMINADA JUSTO SIERRA, BOULEVAR LÁZARO CÁRDENAS, CALZADA HÉCTOR TERÁN TERÁN, BOULEVAR VENUSTIANO CARRANZA, ASÍ COMO DE MANERA PARCIAL LA CALLE 9NA (NOVENA), EN EL TRAMO COMPRENDIDO DE LÁZARO CÁRDENAS Y HASTA INCLUSIVE LA INTERSECCIÓN CON LA CALZADA CETYS, MEJORANDO CON ELLO EFICIENTEMENTE EL FLUJO VEHICULAR NOCTURNO EN UN HORARIO COMPRENDIDO DE AS 23:00 HORAS DEL DÍA ANTERIOR HASTA INCLUSIVE LAS 5:00 HORAS DEL DÍA SIGUIENTE DE LOS SIETE DÍAS DE LA SEMANA, CON SEÑALES INTERMITENTES EN COLOR ÁMBAR O AMARILLO, CON LA INTENCIÓN DE REGULAR EL TRÁFICO VEHÍCULAR NOCTURNO, A BIEN DE BRINDAR MAYOR SEGRIDAD A LOS CONDUCTORES Y CONDUCTORAS EN NUESTRA CIUDAD.', 'NULL', '11/10/2024', 'NULL', 'NULL', 'PROPOSICION', 'NULL', 'NULL', 'NULL', 'LA IMPLEMENTACIÓN DE UN PROGRAMA QUE PERMITA OPTIMIZAR Y SINCRONIZAR EL FUNCIONAMIENTO DE LOS SEMÁFOROS EN LAS VÍAS DE CIRCULACIÓN MÁS IMPORTANTE DE MEXICALI, COMO SON: EN TODA SU LONGITUD, BOULEVAR ADOLFO LÓPEZ MATEOS, BOULEVAR BENITO JÚAREZ Y SU CONTINUACIÓN DENOMINADA JUSTO SIERRA, BOULEVAR LÁZARO CÁRDENAS, CALZADA HÉCTOR TERÁN TERÁN, BOULEVAR VENUSTIANO CARRANZA, ASÍ COMO DE MANERA PARCIAL LA CALLE 9NA (NOVENA), EN EL TRAMO COMPRENDIDO DE LÁZARO CÁRDENAS Y HASTA INCLUSIVE LA INTERSECCIÓN CON LA CALZADA CETYS', 'NULL');
