INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('5', 5, '', '', 'PROPOSICIÓN CON PUNTO DE ACUERDO; ÚNICO: EL PODER LEGISLATIVO DEL ESTADO DE BAJA CALIFORNIA, EXHORTA A LAS PRESIDENCIAS  MUNICIPALES Y CONCEJOS FUNDACIONALES MUNICIPALES DEL ESTADO, PARA QUE INFORME A ESTA LEGISLATURA, QUE ESTRATEGIAS A TOMNADO A EFECTO DE ATENDER EL PROBLEMA DE SALUD PÚBLICA QUE REPRESENTAN LOS MAS DE 300 MIL PERROS EN SITUACIÓN DE CALLE CALLEJERES EN LA CIUDAD DE MEXICALI; ASÍ COMO QUE, INFORME QUE ACCIONES ESPECÍFICAS ESTÁ LLEVANDO A CABO PARA ASEGURAR QUE LOS MEXICALENSES ÍEDAM TRAMSOTAR TRANQUILAMENTE POR LA VÍA PÚBLICA SIN TEMOR A SER ATACADOS POR ESA CLASE DE PERROS, ATAQUE QUE DESAFORTUNADAMENTE PUEDEN ACABAR EN LA PERDIDA DE LA VIDA DE LAS PERSONAS', 'NULL', '', '', 'MXLI, TJ, TKT, PR, SF Y SQ  13/09/2024', 'PROPOSICION', 'NULL', 'NULL', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.14667220718690377.pdf"]', 'ATENDER EL PROBLEMA DE SALUD PÚBLICA QUE REPRESENTAN LOS MAS DE 300 MIL PERROS EN SITUACIÓN DE CALLE OCALLEJERES EN LA CIUDAD DE MEXICALI', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('8', 8, '13/1/2025', '16/1/2025', 'ÚNICO: "EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA PRESIDENTA MUNICIPAL DE MEXICALI, LA MAESTRA NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE A TRAVÉS DE SU SECRETARIO DE SEGURIDAD PÚBLICA EL LICENCIADO LUIS FELIPE CHAN BALTAZAR, LLEVE A CABO LA IMPLEMENTACIÓN DE MEDIDAS URGENTES A BIEN DE REDUCIR ACCIDENTES VIALES Y MEJORAR LA SEGURIDAD EN EL TRÁNSITO DE MEXICALI, A TRAVES DE LA IMPARTICIÓN DE CURSOS, PLÁTICAS Y DESARROLLO DE PROGRAMAS AFINES".', 'APROBADA', '17/1/2025', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN ACCIDENTES VIALES.docx https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/j16wK6mjkJ2H?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=cad52822799f5e3e1c8fdc7fef16eff65b9d5afb693b862370a244f9aa6263e7&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520ACCIDENTES%2520VIALES.docx&x-id=GetObject', 'ACUERDO ACCIDENTES VIALES.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/zAbIUTBie6Fl?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=5812549feaa9fc8917cb45c8615f58233a760718cc2ecaca120e98cf09a09a24&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520ACCIDENTES%2520VIALES.pdf&x-id=GetObject', 'NULL', 'LA IMPLEMENTACIÓN DE MEDIDAS URGENTES A BIEN DE REDUCIR ACCIDENTES VIALES Y MEJORAR LA SEGURIDAD EN EL TRÁNSITO DE MEXICALI, A TRAVES DE LA IMPARTICIÓN DE CURSOS, PLÁTICAS Y DESARROLLO DE PROGRAMAS AFINE', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('9', 9, '24/1/2025', 'NULL', '"EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA PRESIDENTA MUNICIPAL DE MEXICALI, MAESTRA NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE A TRAVÉS DE SU DIRECTOR DE SERVICIOS PÚBLICOS, O DE QUIEN CREA DEBA REALIZARLO, MANIFIESTE A ESTA SOBERANÍA: ¿CÓMO SE LLEVA A CABO LA RECOLECCIÓN DE BASURA, RUTAS Y HORARIOS EN TODAS LAS COLONIAS DE MEXICALI, BAJA CALIFORNIA?, Y SE COMPROMETA EN ADELANTE A REALIZAR LA RECOLECCIÓN DE LOS DESECHOS SÓLIDOS URBANOS  EN ESPECIAL EN LAS ESCUELAS E INSTITUCIONES EDUCATIVAS PÚBLICAS, COMO MÍNIMO DOS VECES A LA SEMANA, CON ATENCIÓN ESPECIAL A AQUELLAS QUE SE UBICAN EN LA ZONA DE NUEVO MEXICALI Y PALACO.”', 'RETIRADA', 'NULL', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN SERVICIO DE LIMPIA ESCUELAS.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/f9n2nGbFNzm3?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=f4505d59c57a4c512070b32c8734026c175b7c67aa2f2a8f70e18c78ab3937f8&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520SERVICIO%2520DE%2520LIMPIA%2520ESCUELAS.pdf&x-id=GetObject', 'NULL', 'NULL', '¿CÓMO SE LLEVA A CABO LA RECOLECCIÓN DE BASURA, RUTAS Y HORARIOS EN TODAS LAS COLONIAS DE MEXICALI, BAJA CALIFORNIA?, Y SE COMPROMETA EN ADELANTE A REALIZAR LA RECOLECCIÓN DE LOS DESECHOS SÓLIDOS URBANOS  EN ESPECIAL EN LAS ESCUELAS E INSTITUCIONES EDUCATIVAS PÚBLICAS, COMO MÍNIMO DOS VECES A LA SEMANA, CON ATENCIÓN ESPECIAL A AQUELLAS QUE SE UBICAN EN LA ZONA DE NUEVO MEXICALI Y PALACO.”', 'NULL');
