INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('17', 17, '7/4/2025', 'NULL', 'ÚNICO: "EL H. CONGRESO DEL ESTADO EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA, MAESTRA MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE, A TRVÉS DEL SECRETARIO DE ECONIMÍA E INNOVACIÓN DEL ESTADO, C.P. KURT IGNACIO HONOLD MORALES, INFORME A ESTA SOBERANÍA RESPECTO A LAS ESTRATEGIAS IMPLEMENTADAS PARA MITIGAR LA CAÍDA EN LA INVERSION EXTRANJERA DIRECTA (IED), ASÍ COMO LAS ACCIONES PROYECTADAS PARA REACTIVAR LA LLEGADA DE NUEVAS INVERSIONES, Y FORTALECER LA REINVERSIÓ DE LAS YA INSTALADA, ASÍ COMO EL CRECIMIENTO ECONÓMICO Y LA GENERACIÓN DE EMPLEOS EN EL CORTO, MEDIANO Y LARGO PLANZO".', 'NULL', 'NULL', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN SRIA ECONOMÍA (IED).pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/CfNRfaOPT654?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=5d5bf64d578db367cb9fc15c54d12a29b5f571cc6a9534ce05e4d2434d015944&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520SRIA%2520ECONOM%25C3%258DA%2520%28IED%29.pdf&x-id=GetObject', 'NULL', 'NULL', 'LAS ESTRATEGIAS IMPLEMENTADAS PARA MITIGAR LA CAÍDA EN LA INVERSION EXTRANJERA DIRECTA (IED), ASÍ COMO LAS ACCIONES PROYECTADAS PARA REACTIVAR LA LLEGADA DE NUEVAS INVERSIONES, Y FORTALECER LA REINVERSIÓ DE LAS YA INSTALADA, ASÍ COMO EL CRECIMIENTO ECONÓMICO Y LA GENERACIÓN DE EMPLEOS EN EL CORTO, MEDIANO Y LARGO PLANZO".', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('18', 18, '21/4/2025', '21/4/2025', 'ÚNICO: " EL H. CONGRESO DEL ESTADO EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA, MAESTRA MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE, A TRAVÉS DEL TITULAR DE LA SECRETARÍA DE HACIENDA Y CRÉDITO PÚBLICO, C.P. MARCO ANTONIO MORENO MEXÍA, INFORME A ESTA SOBERANÍA, CUÁLES SON LAS ACCIONES QUE SE LLEVARÁ A CABO CON LA INTENCIÓN DE IMPLEMENTAR ESTÍMULOS FISCLES PARA LAS EMPESAS EN LA LOCALIDAD QUE CALIFIQUEN PARA ELLO, CON EL FIN DE IMPULSAR LA GENERACIÓN DE EMPLEOS FORMALES, Y ASÍ, FORTALECER LA ECONOMÍA EN EL ESTADO".', 'APROBADA', '11/7/2025', '21/5/2025', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN HACIENDA ESTIMULOS FISCALES.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/Ob19trCNz3x3?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=de48499a0a2f87133941f29884cfcc3ff82a9cc2e40a861df35c595b27651c80&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520HACIENDA%2520ESTIMULOS%2520FISCALES.pdf&x-id=GetObject', 'ACUERDO DIF SITUACION LABORAL CRI TIJUANA.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/3mREl8vukb78?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=c7809618f3a82f3e08d28602d7f5fa09f84a5ddf14f32519d5be036c9a4f0efe&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3