INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('19', 19, '21/4/2025', '21/4/2025', 'ÚNICO: "EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE AL SECRETIO DE AGRICULTURA Y DESARROLLO RURAL DEL ESTADO, ARQ. JUAN MELENDREZ ESPINOZA, PARA QUE INFORME A ESTA SOBERANÍA 1. EL ESTADO ACTUAL DE LAS MESAS DE TRABAJO SOSTENIDAS ENTRE AUTORIDADES FEDERALES, ESTATALES, SISTEMA PRODUCTO TRIGO, INDUSTRIALES YF PRODUCTORES DEL VALLE DE MEXICALI PARA LA DEFINICIÓN DEL PRECIO OBJETIVO DEL TRIGO CICLO OTOÑO-INVIERNO 2024-2025. 2. EL RAZONAMIENTO TÉCNICOY EL MÉTIDODE CÁLCULO DEL PUNTO DE EQUILIBRIO QUE SUSTENTÓ LA DISPERSIÓN DE 15 MILLONES DE PESOS DE APOYO ORIGINALMENTE DESTINADOS A LOS PRODUCTORES, QUE FUERON CANALIZADOS A TRAVÉS DE LA INDUSTRIA".', 'APROBADA', 'NULL', '1/5/2025', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN SRIO AGRICULTURA PRECIO TRIGO Y DISPERCION 15 MILLONES.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/FZA0PYTqcqrw?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=3bca3bdf5fd56db3dd33f4c424e48d705403b1429ddbd91c427c95841af9a4df&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520SRIO%2520AGRICULTURA%2520PRECIO%2520TRIGO%2520Y%2520DISPERCION%252015%2520MILLONES.pdf&x-id=GetObject', 'NULL', 'RA SRIO AGRICULTURA PRECIO TRIGO YDISPERCIÓN 15 MILLONES.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/gUWFwDcAPOZx?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205454Z&X-Amz-Expires=518400&X-Amz-Signature=7bc2db4cd8aa7b2695ccfa1314406a59dda3893eda33765f023b11bdc7b809b0&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27RA%2520SRIO%2520AGRICULTURA%2520PRECIO%2520TRIGO%2520YDISPERCI%25C3%2593N%252015%2520MILLONES.pdf&x-id=GetObject', 'ESTATUS DE LAS MESAS DEL PRECIO OBJETIVO DEL TRIGO PARA ESTE CICLO Y METODO DE CÁLCULO DEL PUNTOD DE EQUILIBRIO CON EL QUE SE SUSTENTÓ LA DISPECION DE LOS 15 MILLONES DE APOYO A PRODUCTORES CANALIZADOS A TRAVÉS DE LA INDUSTRIA.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('20', 20, '19/5/2025', '22/5/2025', 'POR LA QUE SE EXHORTA, RESPETUOSAMENTE, A LA SECRETARÍA DE EDUCACIÓN PÚBLICA PARA QUE ENCOORDINACIÓN CON LA SECRETARÍA DE SALUD Y COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA, EN EL ÁMBITO DE SUS RESPECTIVAS ATRIBUCIONES Y OBLIGACIONES ESTATALES, A FIN DE QUE REFUERCEN LA ATENCIÓN, SEGUIMIENTO Y APOYO A LA SALUD MENTAL DE NIÑAS, NIÑOS Y ADOLESCENTES VÍCTIMAS DE VIOLENCIA ESCOLAR, ASÍ COMO A LAS NIÑAS, NIÑOS Y ADOLESCENTES QUE HAN REALIZADO O REALIZAN ACTOS DE BIOLENCIA ESCOLAR.  ELLO CON EL OBJETIVO DE EVITAR LOS EFECTOS NEGATIVOS QUE PROVOCA LA VIOLENCIA ESCOLAR, TALES COMO LA DEPRESIÓN, ANCIEDAD, CAMBIOS EN LOS PATRONES ALIMENTARIOS Y DEL SUEÑO, PÉRDIDA DE INTERÉS EN LAS ACTIVIDADES QUE SOLÍAN DISFRUTAR; Y EN CASOS GRAVES DONDE SE PRESENTAN AUTOLESIONES O INCLUSO EL SUICIDIO. DICHAS ACCIONES DE ATENCIÓN, SEGUIMIENTO Y APOYO, DEBERÁN APLICARSE CON ESTRICTO APEGO A LOS DERECHOS HUMANOS DE LA COMUIDAD ESTUDIANTIL.', 'APROBADA', '23/5/2025', 'NULL', 'SOLO HA ACUSADO DE RECIBIDO EDUCACIÓN', 'PROPOSICION', 'MYGM PROPOSICION EDUCACION SALUD BULLYNG Y SALUD MENTAL.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/MJrR0U8DRvWj?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=c49b2cc2e86fe76eccc21474c9a9ebf3ece2801bfbffcdf097cb9580f3ee447c&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICION%2520EDUCACION%2520SALUD%2520BULLYNG%2520Y%2520SALUD%2520MENTAL.pdf&x-id=GetObject', 'ACUERDO EDUCACION BULLYNG Y SALUD MENTAL.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/2g9XYY4oQP61?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=71cbbf65d7faf7ed6da30c8e69282ddd107b9f0a166133047d8633a221955a27&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520EDUCACION%2520BULLYNG%2520Y%2520SALUD%2520MENTAL.pdf&x-id=GetObject', 'NULL', 'REFORZAR LA ATENCIÓN A VICTIMAS DE VIOLENCIA ESCOLAR, IMPLEMENTAR URGENTE UN PLAN EMERGENTE CONTRA LA VIOLENCIA ESCOLAR Y TALLERES DE PREVENCIÓN POR PARTE DE LA CEDH', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('21', 21, '6/5/2025', 'NULL', 'NULL', 'NULL', '6/5/2025', 'NULL', 'NO SE PRESENTÓ', 'POSICIONAMIENTO', 'MYGM POSICIONAMIENTO DECISIONES JUNTA GOB ISSSTECALI.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/2OvPRnZiTv7u?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=2bccd91703232909a78590bd3cc4d09c4ba7f9b7d7b5a2f77df48ade1a08da03&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520POSICIONAMIENTO%2520DECISIONES%2520JUNTA%2520GOB%2520ISSSTECALI.pdf&x-id=GetObject', 'NULL', 'NULL', 'POSICIONAMIENTO SOBRE LAS DECISIONES TOMADAS POR LA JUNTA DE GOBIERNO DE ISSSTECALI', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('22', 22, '19/5/2025', 'NULL', 'PRIMERO: SE EXHORTA DE MANERA RESPETUOSA PERO ENÉRGICA, A LA SECRETARÍA DE AGRICULTURA Y DESARROLLO RURAL DEL GOBIERNO FEDERAL (SADER), A TRAVÉS DE SU TITULAR EL ARTQUITECTO JUAN MELÉNDREZ ESPINOZA, PARA QUE CONFIRME Y GARANTICE LA ASIGNACIÓN DE AL MENOS $300 PESOS POR TONELADA DE TRIGO CRISTALINO, COMO APOYO DIRECTO A LOS PRODUCTORES DEL CICLO OTOÑO-INVIERTO 2024-2025.
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('23', 23, '2/6/2025', '5/6/2025', 'ÚNICO: “PRIMERO. ESTA SOBERANÍA EXHORTA DE MANERA URGENTE Y RESPETUOSA A LA PRESIDENTA MUNICIPAL DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE INSTRUYA DE INMEDIATO A QUIEN CONSIDERE NECESARIO, A BIEN DE REALIZAR UNA EVALUACIÓN TÉCNICA, FÍSICA Y OPERATIVA DE TODAS LAS LLAMADAS UNIDADES DEPORTIVAS Y CENTROS PILARES ENTES BAJO LA RESPONSABILIDAD DE BISOM, PARA QUE UNA VEZ CONCLUIDA DICHA EVALUACIÓN, LA HAGA PÚBLICA A LA CIUDADANÍA MEXICALENSE, ASÍ COMO QUE EXPONGA ANTE ESTE H. CONGRESO DE MANERA PRESENCIAL  LOS RESULTADOS OBTENIDOS, TODO ELLO MEDIANTE INFORME DETALLADO. 
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('24', 24, '2/6/2025', '5/6/2025', 'ÚNICO: “EL H. PODER LEGISLATIVO DEL ESTADO DE BAJA CALIFORNIA, REALIZA UN RESPETUOSO EXHORTO A DIANA ASUNCIÓN PÉREZ ÁLVAREZ, DIRECTORA GENERAL DEL SISTEMA PARA EL DESARROLLO INTEGRAL DE LA FAMILIA DE BAJA CALIFORNIA; LUIS GILBERTO GALLEGO CORTEZ, SECRETARIO DE EDUCACIÓN DE BAJA CALIFORNIA Y MARÍA ELENA ANDRADE RAMÍREZ, FISCAL GENERAL DEL ESTADO DE BAJA CALIFORNIA A EFECTO DE QUE EN EL ÁMBITO DE SUS ATRIBUCIONES INVESTIGUEN LOS HECHOS DENUNCIADOS EN CONTRA DEL CENTRO EDUCATIVO CHILDREN´S SCHOOL Y EN SU CASO, TOMEN LAS MEDIDAS NECESARIAS PARA SALVAGUARDAR LA INTEGRIDAD DE LOS NIÑOS.”', 'APROBADA', '6/6/2025', 'NULL', 'DIF Y EDUCACIÓN RECIBIERON EL ACUERDO EL MISMO DÍA 6 DE JUNIO DE 2025', 'PROPOSICION', 'MYGM PROPOSICIÓN FISCALÍA CHILDREN''S SCHOOL.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/aTVxujQTGqgp?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=b7e8f73255470f02177e01056281ff17d7a4d7aea9b90d42f3ee34ec890cf672&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520FISCAL%25C3%258DA%2520CHILDREN%27S%2520SCHOOL.pdf&x-id=GetObject', 'CR ACUSE EECIBIDO DIF EDUCACION Y FISCALIA CHILDRENS SCHOOL.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/n1rhSjY4874p?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=271144304a7a3264243e5eae268