INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('25', 25, '17/6/2025', '19/6/2025', '“ÚNICO: ESTA SOBERANÍA EXHORTE A LA COMISIÓN FEDERAL DE ELECTRICIDAD A TRAVÉS DE MARCELINO PALERO GONZÁLEZ Y JOEL VILLAVICENCIO VILLALEJOS, AMBOS EN SU CALIDAD DE ADMINISTRADORES, PARA QUE EN ESTA TEMPORADA DE VERANO MANTENGA EN PERFECTO ESTADO LAS PLANTAS GENERADORAS DE SUMINISTRO ELÉCTRICO, LAS REDES Y SISTEMA QUE PERMITEN SU ABASTECIMIENTO Y UNA PROTECCIÓN PERMANENTE A LA INFRAESTRUCTURA ELÉCTRICA QUE PERMITAN LA PROTECCIÓN DE APAGONES GENERALIZADOS; ASIMISMO, A TRAVÉS DE LOS MEDIOS MÁS IDÓNEOS INFORMEN PREVIAMENTE A LA POBLACIÓN, LOS LUGARES, FECHAS Y HORARIOS EN QUE REALIZARAN APAGONES PROGRAMADOS PARA LLEVAR A CABO MANTENIMIENTO, LABORES TÉCNICAS EN LA RED DE DISTRIBUCIÓN O POR MOTIVOS DE SEGURIDAD ANTE FENÓMENOS METEOROLÓGICOS EXTREMOS”', 'NULL', 'NULL', 'NULL', 'SE CAMBIÓ NOMBRE DE ADMINISTRADOR POR ACUERDO CON JAVIER SÁNCHEZ DE PARLAMENTARIOS', 'PROPOSICION', 'MYGM PROPOSICION CFE MMTO Y BUEN ESTADO SUMINISTRO ELECTRICO.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/2CrYDn9ZJod7?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=1045f8eef040ab35f4adfbd02a7d580fe7756b6554e2afd5fbf226f4feffd2e4&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICION%2520CFE%2520MMTO%2520Y%2520BUEN%2520ESTADO%2520SUMINISTRO%2520ELECTRICO.pdf&x-id=GetObject', 'ACUERDO CFE MMTO SISTEMA ELÉCTRICO .pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/gIqJsL6vy3Fm?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=cc589f2a93122a7fd4d2e705601ee309630f15f78d5160f4f28d6cf07d4afb96&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520CFE%2520MMTO%2520SISTEMA%2520EL%25C3%2589CTRICO%2520.pdf&x-id=GetObject,ACUERDO CFE MMTO SISTEMA ELÉCTRICO MXLI.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/TBhj0jKwNdT8?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=a7d4a60fab0eeace84ef7cbcab3aaedb896de9723ba23c87408b649f3e11e7e5&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520CFE%2520MMTO%2520SISTEMA%2520EL%25C3%2589CTRICO%2520MXLI.pdf&x-id=GetObject', 'NULL', 'QUE LA CFE MANTENGA EN PERFECTO ESTADO LAS PLANTAS GENERADORAS DE SUMINISTRO ELÉCTRICO, Y QUE AVISEN CON TIEMPO DE APAGONES PROGRAMADOS PARA MMTO.', 'NULL');
