INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('27', 27, '30/6/2025', '3/7/2025', 'PRIMERO: ESTA SOBERANÍA EXHORTE A LA SECRETARÍA GENERAL DE GOBIERNO, A TRAVÉS DE SU TITULAR, ALFREDO ÁLVAREZ CÁRDENAS, A BIEN DE INSTRUIR A LA DIRECTORA DEL REGISTRO CIVIL ESTATAL, ELIZABETH MÁRQUEZ SAAVEDRA, PARA QUE ESTA ÚLTIMA, REALICE LAS ACCIONES NECESARIAS EN EL ÁMBITO DE SUS ATRIBUCIONES DENTRO DEL REGISTRO CIVIL ESTATAL, E INSTAR A LAS OFICIALÍAS DEL REGISTRO CIVIL DE LOS SIETE MUNICIPIOS DEL ESTADO, REALICEN CON LA MAYOR PROBIDAD Y CUIDADO EL EXTRACTO DE LAS ACTAS QUE EXPIDEN, Y EN SU CASO, ATIENDAN CON PRIORIDAD Y PRONTITUD LA CORRECCIÓN DE LOS ERRORES EXISTENTES, CONFORME LA INFORMACIÓN PLASMADO EN LA COPIA FIEL DEL LIBRO DEL ACTA DE QUE SE TRATE.
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('29', 29, '11/8/2025', '14/8/2025', '“ÚNICO: EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO MTRA. MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE A TRAVÉS DE LA SECRETARÍA DE EDUCACIÓN LIC. IRMA MARTÍNEZ MANRÍQUEZ, DEL SECRETARIO DE HACIENDA C.P. MARCO ANTONIO MORENO MEXÍA Y DEL SECRETARIO DE INFRAESTRUCTURA ING. ARTURO ESPINOZA JARAMILLO, SE INFORME A ESTA SOBERANÍA, LO SIGUIENTE: 
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('30', 30, '25/8/2025', '28/8/2025', '“PRIMERO: El H. Congreso del Estado de Baja California, exhorta respetuosamente al Titular de la Comisión Nacional del Agua (CONAGUA) en Baja California, Manuel Guerrero Luna; a bien que mantenga desazolvados los drenes que se encuentran a su cargo y cuidado dentro de la mancha urbana, de manera importante al este de esta Ciudad;
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('31', 31, '11/8/2025', '28/8/2025', '“ÚNICO. EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ; AL SECRETARIO DEL AYUNTAMIENTO, RODRIGO LLANTADA ÁVILA; AL TESORERO MUNICIPAL, ROGER SOSA ALAFITA; Y A LA OFICIAL MAYOR, CLAUDIA LORENIA BELTRÁN GONZÁLEZ; A BIEN QUE BRINDEN SU RESPALDO INSTITUCIONAL, INCORPOREN EL PROYECTO DEL CENTRO MUNICIPAL DE CONTROL ANIMAL ZONA VALLE AL PLAN Y PRESUPUESTO MUNICIPAL, IMPULSEN LAS REFORMAS REGLAMENTARIAS NECESARIAS, FORTALEZCAN LA PARTICIPACIÓN COMUNITARIA MEDIANTE COMITÉS VECINALES, Y FORMALICEN LA COLABORACIÓN CON EL SANTUARIO MILLY PARA GARANTIZAR UNA ATENCIÓN INTEGRAL Y SOSTENIBLE AL BIENESTAR ANIMAL EN EL VALLE DE MEXICALI”', 'APROBADA', '4/9/2025', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN CEMCA Y MILLY VALLE.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/aSXp64vmYoJ0?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=f852fbd99bb469a05f485f1877916aad2bcfa1f675e24a27e619d61c0bcb765e&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520CEMCA%2520Y%2520MILLY%2520VALLE.pdf&x-id=GetObject', 'ACUERDO AYMTO MXLI SRIO AYMTO TESORERO AYMTO OF MAYOR MCPAL  PERROS ZONA VALLE.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/eKX9t7ihrB8X?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=33ec345d5f7e3faf5cc22525323829c14e8c2288619b56bed188d3010d1bae19&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520AYMTO%2520MXLI%2520SRIO%2520AYMTO%2520TESORERO%2520AYMTO%2520OF%2520MAYOR%2520MCPAL%2520%2520PERROS%2520ZONA%2520VALLE.pdf&x-id=GetObject', 'NULL', 'SE REALICEN LOS ACCIONES NECESARIAS PARA INCORPORAR UN CEMCA ZONA VALLE Y QUE SE IMPULSEN LAS REFORMAS REGLAMENTARIAS PARA FORTALECER EL SANTUARIO MILLY QUE ATIENDA TAMBIEN ZONA VALLE.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('47', NULL, '23/9/2025', '25/9/2025', 'ÚNICO. EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DEL H. AYUNTAMIENTO DE PLAYAS DE ROSARITO MTRA. MARÍA DEL ROCÍO ADAME MUÑOZ, AL OFICIAL MAYOR LIC. RAMON CELESTINO MEDRANO AGUILAR Y AL SECRETRIO DE SEGURIDAD CIUDADANA LIC. HÉCTOR MANZO RUVALCABA, A BIEN QUE DEN CUMPLIMIENTO INMEDIATO A LA RESOLUCIÓN DE LA SINDICATURA MUNICIPAL Y SE REINCORPOREN AL SERVICIO ACTIVO A LOS 33 POLICÍAS MUNICIPALES, GARANTIZANDO SU PAGO ÍNTEGRO Y EL FORTALECIMIENTO DE LA SEGURIDAD PÚBLICA EN BENEFICIO DE LA CIUDADANÍA ROSARITENSE.', 'APROBADA', 'NULL', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN CUMPLIMIENTO RESOLUCIÓN 33 DE ROSARITO.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/VkwWPcZ3JMn2?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=b8f75826edac6f0f1cfa142dc0dff28c7a66a18578d12ac8afbd1b1b974cbca0&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520CUMPLIMIENTO%2520RESOLUCI%25C3%2593N%252033%2520DE%2520ROSARITO.pdf&x-id=GetObject', 'NULL', 'NULL', 'LA PRESIDENTA MUNICIPAL DE ROSARITO ACATE LA RESOLUCIÓN DE LA SINDICATURA MUNICIPAL Y SE REINCORPOREN A SERVICIO ACTIVO LOS 33 POLICÍAS.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('32', 62, '3/11/2025', '6/11/2025', '“ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EMITE UN ATENTO Y RESPETUOSO EXHORTO AL AYUNTAMIENTO DE MEXICALI, POR CONDUCTO DE LA PRESIDENTA MUNICIPAL NORMA ALICIA BUSTAMANTE MARTÍNEZ; AL DIRECTOR DE OBRAS PÚBLICAS MUNICIPALES, ALBERTO IBARRA OJEDA; AL DIRECTOR DE  ALUMBRADO PÚBLICO, JUAN FRANCISCO GARZA CESEÑA Y AL DIRECTOR DE SEGURIDAD PÚBLICA MUNICIPAL, LUIS FELIPE CHAN BALTAZAR, PARA QUE IMPLEMENTEN DE INMEDIATO UN PLAN INTEGRAL DE ATENCIÓN URBANA EN LA COLONIA SATURNO Y SUS ALREDEDORES, CON ACCIONES PRIORITARIAS EN MATERIA DE PAVIMENTACIÓN, ILUMINACIÓN, SEGURIDAD PÚBLICA Y SEMAFORIZACIÓN; INFORMANDO A ESTA SOBERANÍA EN UN PLAZO NO MAYOR A TREINTA DÍAS, LOS AVANCES Y RECURSOS EJERCIDOS DURANTE EL PRESENTE EJERCICIO FISCAL, ASÍ COMO LOS QUE PRETENDE INVERTIR EN FAVOR DELA COMUNIDAD PARA EL 2026 Y QUE SE DEBERÁ SOLICITAR EN SU PRESUPUESTO DE EGRESOS PARA EL AÑO 2026”, MISMO QUE TENDRÁ QUE REALIZARSE BAJO LOS SIGUIENTES PREMISAS:
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('34', 64, '6/10/2025', '9/10/2025', 'ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EMITE UN RESPETUOSO EXHORTO AL GENERAL BRIGADIER ESTADO MAYOR LAUREANO CARRILLO RODRÍGUEZ, SECRETARIO DE SEGURIDAD CIUDADANA DEL ESTADO DE BAJA CALIFORNIA; A LA DRA. MARÍA ELENA ANDRADE RAMÍREZ, FISCAL GENERAL DEL ESTADO DE BAJA CALIFORNIA; Y AL MTRO. LUIS FELIPE CHAN BALTAZAR, DIRECTOR DE SEGURIDAD PÚBLICA MUNICIPAL, PARA QUE FORTALEZCAN LOS PROTOCOLOS DE PREVENCIÓN, COORDINACIÓN Y ATENCIÓN EN ESCUELAS, ESPACIOS PÚBLICOS Y EVENTOS MASIVOS, AL TENOR DE LOS SIGUIENTES PUNTOS:
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('35', 65, '24/11/2025', '27/11/2025', '“ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JOSÉ ADRIÁN MEDINA AMARILLAS, SECRETARIO DE SALUD DEL ESTADO DE BAJA CALIFORNIA; A IRMA MARTÍNEZ MANRÍQUEZ, SECRETARIA DE EDUCACIÓN DEL ESTADO DE BAJA CALIFORNIA; A MÓNICA VARGAS NÚÑEZ, SECRETARIA DE AGRICULTURA Y DESARROLLO RURAL DEL ESTADO DE BAJA CALIFORNIA; Y A ALMA ROSA GARCÍA JUÁREZ, SECRETARIA DE PESCA Y ACUACULTURA DEL ESTADO DE BAJA CALIFORNIA; A QUE REALICEN UN ANÁLISIS EXHAUSTIVO Y DEL PRESUPUESTO EJERCIDO EN 2024 Y DEL PROYECTADO PARA 2025, IDENTIFIQUEN REZAGOS OPERATIVOS, AHORROS, DESAHORROS, NECESIDADES INSTITUCIONALES Y ELABOREN CON BASE EN ELLO, UNA PROPUESTA PRESUPUESTAL CON JUSTIFICACIÓN TÉCNICA PARA EL PRESUPUESTO DE EGRESOS 2026 TENDIENTE A QUE SEA SIGNIFICATIVAMENTE MAYOR, SUFICIENTE Y DEBIDAMENTE JUSTIFICADA, FORTALECIENDO INFRAESTRUCTURA, SERVICIOS, PROGRAMAS, EQUIPAMIENTO, PERSONAL Y ATENCIÓN CIUDADANA, ASÍ COMO QUE LA DISTRIBUCIÓN DE DICHO PRESUPUESTO, SEA EQUITATIVA CONSIDERANDO LAS NECESIDADES ESPECÍFICAS DE CADA UNO DE LOS SIETE MUNICIPIOS QUE CONFORMAN EL ESTADO; A BIEN QUE EL DÍA DE SU REVISIÓN Y APROBACIÓN POR ESTA SOBERANÍA, SEA PARA SUS EFECTOS TOMADA EN CUENTA ESA JUSTIFICACIÓN TÉCNICA, DENTRO DE LA SESIÓN DE PLENO CORRESPONDIENTE AL PROCESO DE APROBACIÓN DEL PRESUPUESTO DE EGRESOS 2026; POR ÚLTIMO AL SECRETARIO DE HACIENDA DEL ESTADO DE BAJA CALIFORNIA, JOSÉ ANDRÉS PULIDO SAAVEDRA; PARA QUE ATIENDA DE MANERA DILIGENTE, LAS NECESIDADES Y JUSTIFICACIONES DE LOS SECRETARIOS SEÑALADOS EN ESTE PUNTO DE ACUERDO Y LES BRINDE LAS FACILIDADES DE LA OBTENCIÓN DE MAYOR RECURSO ECONÓMICO QUE SERÁ UTILIZADO EN LOS DIFERENTES PROGRAMAS DE SUS ENCARGOS PARA BENEFICIO DE LA COMUNIDAD BAJACALIFORNIANA.”', 'APROBADA', 'NULL', '12/12/2025', 'RESPUESTA 1SRIA SALUD, 2SRIA PESCA 161225', 'PROPOSICION', 'MYGM PROPOSICIÓN AGRICULTURA EDUCACIÓN SALUD JUSTIFICACIÓN TÉCNICA PRESUPUESTO 26.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/awbMKEkjkFv0?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=0694910728d843d73f25126fa4d97538893e590bd5b953a40ff4f54746e97dd6&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520AGRICULTURA%2520EDUCACI%25C3%2593N%2520SALUD%2520JUSTIFICACI%25C3%2593N%2520T%25C3%2589CNICA%2520PRESUPUESTO%252026.pdf&x-id=GetObject', 'ACUERDO SALUD, EDUCACIÓN 12 AMBIENTE AGRICULTURA HDA JUSTIFICACIÓN TÉCNICA PRESUPUESTO 2026.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/l11H8fJPLS5T?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=78f2baee87aae78b78652836dc5bce84201e243656b29de2e087167acf406898&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520SALUD%252C%2520EDUCACI%25C3%2593N%252012%2520AMBIENTE%2520AGRICULTURA%2520HDA%2520JUSTIFICACI%25C3%2593N%2520T%25C3%2589CNICA%2520PRESUPUESTO%25202026.pdf&x-id=GetObject', 'RA SRIA SALUD ELABORACIÓN PRESUPUESTO 2026 CON JUSTIFICACION TÉCNICA.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/NskxHmgnLJFG?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205454Z&X-Amz-Expires=518400&X-Amz-Signature=59e9360e919675c0f2022d5bc99545ea8385ac5ff7d00420f