INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('40', 98, '2026-01-12', '2026-01-15', '"ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A ARTURO ESPINOSA JARAMILLO SECRETARIO DE INFRAESTRUCTURA, DESARROLLO URBANO Y REORDENAMIENTO TERRITORIAL EN EL ESTADO, INFORMEN A ESTA SOBERANÍA LOS SIGUIENTES PUNTOS: PRIMERO: PARA QUE EN UN TÉRMINO QUE NO DEBERÁ EXCEDER DE TREINTA DÍAS NATURALES, SE INFORME LA CALIDAD DE LAS REPARACIONES QUE LA EMPRESA CONSTRUCTORA CADENA REALIZÓ A LAS DEFICIENCIAS EN EL DISTRIBUIDOR VIAL LÁZARO CÁRDENAS-VENUSTIANO CARRANZA”. SEGUNDO: PARA QUE EN UN TÉRMINO QUE NO DEBERÁ EXCEDER DE TREINTA DÍAS NATURALES, SE INFORME EL ALCANCE DE LA RESPONSABILIDAD DE LA CONSTRUCTORA CADENA RESPECTO LA CONSTRUCCIÓN Y REPARACIÓN DE LAS DEFICIENCIAS EN EL DISTRIBUIDOR VIAL LÁZARO CÁRDENAS-VENUSTIANO CARRANZA. TERCERO: PARA QUE EN UN TÉRMINO QUE NO DEBERÁ EXCEDER DE TREINTA DÍAS NATURALES, INFORME SI AÚN ESTÁ VIGENTE LA GARANTÍA Y/O FIANZA OTORGADA POR LA CONSTRUCTORA CADENA EN LA REALIZACIÓN DISTRIBUIDOR VIAL LÁZARO CÁRDENAS-VENUSTIANO CARRANZA. CUARTO: PARA QUE EN UN TÉRMINO QUE NO DEBERÁ EXCEDER DE TREINTA DÍAS NATURALES, INFORME LA RAZÓN POR LA QUE ADMITIÓ RECIBIR EN ESAS CONDICIONES Y CON ESAS DEFICIENCIAS Y COMO OBRA CONCLUIDA EL DISTRIBUIDOR VIAL LÁZARO CÁRDENAS-VENUSTIANO CARRANZA”', 'APROBADA', '', '', 'NULL', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.07862458061172972.pdf"]', 'ACUERDO ALGODONEROS 7000 HECTAREA.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/QfvzyavX6uNf?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205454Z&X-Amz-Expires=518400&X-Amz-Signature=978256e822756a81b37fa7ef51b730d4b42f9c038bbdef55a2b59d8a32244463&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520ALGODONEROS%25207000%2520HECTAREA.pdf&x-id=GetObject', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8734798511348689.pdf"]', 'EXHORTAR GOBIERNO BC, SRIA INFRAESTRUCTURA CALIDAD DE REPARACIONES Y LA VIGENCIA DE GARANTÍA A CONSTRUCTORA CADENA DEL DISTRTIBUIDOR VIAL LÁZARO CARDENAS-CARRANZA.', 'NA');
