INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('44', NULL, '21/10/2025', '23/10/2025', '“ÚNICO: EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A MARINA DEL PILAR ÁVILA OLMEDA, GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA; NORMA ALICIA BUSTAMANTE MARTÍNEZ, PRESIDENTA MUNICIPAL DE MEXICALI; CLAUDIA JOSEFINA AGATÓN MUÑIZ, PRESIDENTA MUNICIPAL DE ENSENADA, MARÍA DEL ROCÍO ADAME MUÑOZ, PRESIDENTA MUNICIPAL DE PLAYAS DE ROSARITO; MIRIAM ELIZABETH CANO NÚÑEZ, PRESIDENTA MUNICIPAL DE SAN QUINTÍN, ISMAEL BURGUEÑO RUIZ, PRESIDENTE MUNICIPAL DE TIJUANA; ROMÁN COTA MUÑOZ, PRESIDENTE MUNICIPAL DE TECATE; JOSÉ LUIS DAGNINO LÓPEZ, PRESIDENTE MUNICIPAL DE SAN FELIPE; TODOS LOS MUNICIPIOS QUE CONFORMAN EL ESTADO DE BAJA CALIFORNIA, A EFECTO DE QUE GIREN LOS OFICIOS CORRESPONDIENTES Y ORDENEN A LAS DEPENDENCIAS QUE CONFORMAN SU RESPECTIVA ADMINISTRACIÓN, PARA QUE CUMPLAN PUNTUALMENTE ANTE LAS AUTORIDADES HACENDARIAS, DE SERVICIOS MÉDICOS Y CUALQUIERA A LA QUE SE LE DEBAN DE RENDIR EMOLUMENTOS RETENIDOS A LOS TRABAJADORES Y QUE CUMPLAN CON LAS OBLIGACIONES QUE LEGALMENTE LES ATAÑEN, SEA COMO DEPENDENCIA O COMO PATRÓN”.', 'APROBADA', 'NULL', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN ALCALDÍAS 7 AYMTOS. CUMPLIMIENTO DE CONTRIBUCIONES .pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/qjrKweIASxL1?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=630010fcd14b62a47752d004682432d0d56e2830a4c30c041bd42074dfab4f1f&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520ALCALD%25C3%258DAS%25207%2520AYMTOS.%2520CUMPLIMIENTO%2520DE%2520CONTRIBUCIONES%2520.pdf&x-id=GetObject', 'NULL', 'NULL', 'EXHORTAR A LAS ALCALDÍAS DE LOS 7 AYMTOS., PARA QUE SUS DEPENDENCIAS CUMPLAN PUNTUALMENTE CON LAS CONTRIBUCIONES ANTE LAS AUTORIDADES HACENDARIAS.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('45', 161, '26/1/2026', '29/1/2026', '"ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JOSÉ ANDRÉS PULIDO SAAVEDRA, SECRETARIO DE HACIENDA DEL ESTADO DE BAJA CALIFORNIA; A ARTURO ESPINOZA JARAMILLO, SECRETARIO DE INFRAESTRUCTURA, DESARROLLO URBANO Y REORDENACIÓN TERRITORIAL; Y KURT IGNACIO HONOLD MORALES, SECRETARIO DE ECONOMÍA E INNOVACIÓN, PARA QUE, EN EL ÁMBITO DE SUS RESPECTIVAS COMPETENCIAS, REVISEN, REEVALÚEN Y AMPLÍEN LA PROGRAMACIÓN PRESUPUESTAL DEL PROGRAMA ANUAL DE OBRA PÚBLICA 2026, A FIN DE IMPULSAR EL CRECIMIENTO ECONÓMICO, FORTALECER LA COMPETITIVIDAD ESTATAL, ATRAER INVERSIONES PRODUCTIVAS Y GENERAR NUEVOS EMPLEOS FORMALES EN BAJA CALIFORNIA”.', 'NULL', 'NULL', 'NULL', 'NULL', 'PROPOSICION', 'MYGM PROPOSICIÓN SRIO HDA, ECONOMÍA E INFRAESTRUCTURA AMPLIAR PRESUPUESTO 2026.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/vcChrnQBDPtT?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=dc5f55bf1e3f2c9448a84af52e092ddb13828a1783fe19b27093ef1681659b57&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520SRIO%2520HDA%252C%2520ECONOM%25C3%258DA%2520E%2520INFRAESTRUCTURA%2520AMPLIAR%2520PRESUPUESTO%25202026.pdf&x-id=GetObject', 'NULL', 'NULL', 'EXHORTAR SECRETARIOS DE ECONOMÍA, HACIENDA E INFRAESTRUCTURA REVISEN, REEVALÚEN Y AMPLÍEN LA PROGRAMACIÓN PESUPUESTAL DEL PROGRAMA ANUAL DE OBRA PÚBLICA 2026, A FIN DE IMPULSAR EL CRECIMIENTO ECONÓMICO, FORTALECER LA COMPETITIVIDAD ESTATAL, ATRAER INVERSIONES PRODUCTIVAS Y GENERAR NUEVOS EMPLEOS FORMALES EN BC.', 'NULL');
