INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('48', 196, '8/9/2025', '11/9/2025', '“EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ; AL DIRECTOR DE MOVILIDAD SUSTENTABLE DE MEXICALI (DIMOS), RAMÓN RAMSÉS ROMERO ARAIZA; AL DIRECTOR DE SERVICIOS PÚBLICOS MUNICIPALES DEL XXV AYUNTAMIENTO DE MEXICALI, JUAN FRANCISCO GARZA CESEÑA; AL TITULAR DE LA SECRETARÍA DE INFRAESTRUCTURA, DESARROLLO URBANO Y REORDENACIÓN TERRITORIAL, ING. ARTURO ESPINOZA JARAMILLO; ASÍ COMO AL DIRECTOR DEL INSTITUTO DE MOVILIDAD SUSTENTABLE Y TRANSPORTE DEL ESTADO DE BAJA CALIFORNIA (IMOS), JORGE ALBERTO GUTIÉRREZ TOPETE”.', 'APROBADA', 'NULL', 'NULL', 'LLEGO RESPUESTA ACUERDO 11 NOV 2025', 'PROPOSICION', 'MYGM PROPOSICIÓN PDTA. MXLI, IMOS, SRIA. DUyRT y SPM NOMENCLATURA .pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/cQA48ADabpdq?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205453Z&X-Amz-Expires=518400&X-Amz-Signature=3ee79f4a85f532035ca03f30f8fbfea3d46251b2051c4bf46c89e45a117d4eaf&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27MYGM%2520PROPOSICI%25C3%2593N%2520PDTA.%2520MXLI%252C%2520IMOS%252C%2520SRIA.%2520DUyRT%2520y%2520SPM%2520NOMENCLATURA%2520.pdf&x-id=GetObject', 'NULL', 'NULL', 'QUES LA SRIA. DE INFRAESTRUCTURA, IMOS, DIMOS, SERVICIOS PÚBLICOS Y PDTA. MUNICIPAL REVEVISEN LA NOMENCLATURA, SEÑALIZACIÓN Y SEMAFORIZACIÓN VIAL Y SE INSTALEN O REPONGAN EN CASO NECESARIO.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('49', 197, '9/2/2026', '12/2/2026', '"ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A ALEJANDRO ARREGUI IBARRA, SECRETARIO DEL TRABAJO Y PREVISIÓN SOCIAL DEL ESTADO, PARA QUE INFORME EL AVANCE RESPECTO LA DEFENSA DE LOS DERECHOS LABORALES DE LOS MÁS DE CUATROCIENTOS TRABAJADORES QUE PERDIERON SU TRABAJO POR EL CIERRE DE OPERACIONES EN MEXICALI, DE LA EMPRESA AUTOLITE Y TOME LAS MEDIDAS CAUTELARES Y LEGALES CONDUCENTES ANTE, EL CIERRE DE DICHA EMPRESA EN ESTE MUNICIPIO”.', 'APROBADA', '17/2/2026', 'NULL', 'NULL', 'PROPOSICION', 'NULL', 'NULL', 'NULL', 'PRESENTAR AVANCES RESPECTO LA DEFENSA DE LOS DERECHOS LABORALES DE LOS MÁS DE CUATROCIENTOS TRAB AJADORES QUE PERDIERON SU TRABAJO PO EL CIERRE DE OPERACIONES EN ETA CIUDAD DE LA EMPRESA AUTOLITE, ASÍ COMO QUE SE INFORME CUALES SON Y SERÁN LAS MEDIDAS CAUTELARES Y LEGALES PARA QUE LA EMPRESA NO DESMANTELE O ETIRE LA MAQUINARIA DEL INMUEBLE DONDE TENÍA ASENTADO SU CENTRO DE OPERACIONES, CON LA FINALIDAD QUE SIRVA EN BENEFICIO DE LOS MÁS DE CUATROCIENTOS TRABAJADORES QUE AHÍ LABORABAN.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('50', 198, '8/9/2025', '11/9/2025', '“ÚNICO. “EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DEL H. AYUNTAMIENTO DE SAN QUINTÍN, MIRIAM CANO NÚÑEZ, PARA QUE EN USO DE SUS FACULTADES Y ATRIBUCIONES GIRE INSTRUCCIONES AL DIRECTOR DE SEGURIDAD PÚBLICA MUNICIPAL, ALBERTO SARABIA, Y A LA OFICIALÍA MAYOR DEL AYUNTAMIENTO BRENDA JOSEFINA SEPÚLVEDA ÁLVAREZ, A BIEN QUE SE IMPONGA DE LOS SIGUIENTES PUNTOS: 
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('51', NULL, 'NULL', '6/11/2025', '“ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE LA COMISIÓN NACIONAL DEL AGUA (CONAGUA)A NIVEL FEDERAL, A TRAVÉS DE SU TITULAR EFRAÍN MORALES LÓPEZ; A LA COMISIÓN NACIONAL DEL AGUA (CONAGUA) EN BAJA CALIFORNIA, A TRAVÉS DE SU TITULAR MANUEL GUERRERO LUNA; A LA SECRETARÍA DE AGRICULTURA Y DESARROLLO RURAL DEL ESTADO DE BAJA CALIFORNIA, A TRAVÉS DE SU TITULAR MÓNICA VARGAS NÚÑEZ; A LA SECRETARÍA PARA EL MANEJO, SANEAMIENTO Y PROTECCIÓN DEL AGUA, A TRAVÉS DE SU TITULAR VÍCTOR DANIEL AMADOR BARRAGÁN; A FIN DE QUE SE GARANTICE LA PROTECCIÓN DEL PATRIMONIO HÍDRICO Y AGRÍCOLA DEL VALLE DE MEXICALI, SALVAGUARDANDO LA CERTEZA JURÍDICA, LA CONTINUIDAD PRODUCTIVA Y LA PARTICIPACIÓN DIRECTA DE LOS USUARIOS DEL DISTRITO DE RIEGO 014 RÍO COLORADO DENTRO DEL PROCESO DE ANÁLISIS Y EVENTUAL APROBACIÓN DE LA LEY GENERAL DE AGUAS Y DE LA REFORMA A LA LEY DE AGUAS NACIONALES, PRIORIZANDO EL DIÁLOGO CON LOS PRODUCTORES Y LA PRESERVACIÓN DEL DESARROLLO ECONÓMICO Y SOCIAL DE LA REGIÓN”, MISMO QUE TENDRÁ QUE REALIZARSE BAJO LOS SIGUIENTES PUNTOS:
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('78', NULL, '2026-08-10', '2026-08-27', '“ÚNICO: EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A ARMANDO CARRAZCO LÓPEZ, DIRECTOR GENERAL DE LA COMISIÓN ESTATAL DE SERVICIOS PÚBLICOS DE MEXICALI (CESPM) PARA QUE, ATENDIENDO A LA CRÍTICA SITUACIÓN CLIMÁTICA Y ECONÓMICA DE LA REGIÓN, AUTORICE A LA BREVEDAD MEDIANTE OFICIO DIRIGIDO A QUIEN CONSIDERE CONVENIENTE LO SIGUIENTE, SE AUTORICE PRÓRROGA GENERALIZADA DE POR LO MENOS UN MES ADICIONAL Y ADEMÁS, SE IMPLEMENTE UN MECANISMO OBLIGATORIO DE NOTIFICACIÓN PREVIA CON UN MÍNIMO DE 30 DÍAS NATURALES DE ANTERIORIDAD AL CORTE DE AGUA POTABLE, TODO ELLO EN RELACIÓN CON LAS MICRO, PEQUEÑAS Y MEDIANAS EMPRESAS (MIPYMES) DE MEXICALI Y SU VALLE.”', '', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7470740778426571.pdf"]', NULL, NULL, 'APOYAR E INCENTIVAR A LAS PEQUEÑAS Y MEDIANAS EMPRESAS DE LA LOCALIDAD, SOLICITANDO EL ALTO AL CORTE DE SERVICIO DE AGUA POTABLE EN LOS MESES DE CLIMA CALUROSAMENTE EXTREMO DE NUESTRA CIUDAD.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('53', 28, '2025-11-24', '2025-01-27', '', 'APROBADA', '2025-12-26', '2026-02-25', 'NULL', 'PROPOSICION', NULL, NULL, NULL, 'REVISAR LA PROPUESTA DE REFORMA AL ARTÍCULO 22 DE LA LEY DE AGUAS NACIONALES, A FIN DE GARANTIZAR LA PARTICIPACIÓN DIGNA, DIRECTA Y CON VOZ DE LOS AGRICULTORES DEL VALLE DE MEXICALI', 'NA');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('41', 128, '2025-11-24', '2025-11-27', '“ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA C. CLAUDIA SHEINBAUM PARDO, PRESIDENTA CONSTITUCIONAL DE LOS ESTADOS UNIDOS MEXICANOS; AL C. RICARDO MONREAL ÁVILA, PRESIDENTE DE LA JUNTA DE COORDINACIÓN POLÍTICA DE LA CÁMARA DE DIPUTADOS; A LA C. KENIA LÓPEZ RABADÁN, PRESIDENTA DE LA MESA DIRECTIVA DE LA CÁMARA DE DIPUTADOS; A LA C. LAURA ITZEL CASTILLO JUÁREZ, PRESIDENTA DE LA MESA DIRECTIVA DE LA CÁMARA DE SENADORES; Y AL C. ADÁN AUGUSTO LÓPEZ HERNÁNDEZ, PRESIDENTE DE LA JUNTA DE COORDINACIÓN POLÍTICA DE LA CÁMARA DE SENADORES, PARA QUE, EN EL ÁMBITO DE SUS ATRIBUCIONES: REVISEN LA PROPUESTA DE REFORMA AL ARTÍCULO 22 DE LA LEY DE AGUAS NACIONALES, A FIN DE GARANTIZAR LA PARTICIPACIÓN DIGNA, DIRECTA Y CON VOZ DE LOS AGRICULTORES DEL VALLE DE MEXICALI Y EVITAR UN MARCO NORMATIVO QUE LÍMITE TRANSMISIÓN DE CONCESIONES DE AGUA Y GENEREN AFECTACIONES A LA CERTEZA JURÍDICA DE LOS AGRICULTORES Y LA PRODUCTIVIDAD AGRÍCOLA DEL VALLE DE MEXICALI”.', 'APROBADA', '2025-12-26', '2026-02-25', 'NULL', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.9843856952585659.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.9963424690308819.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.643545879516662.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.28463323149588593.pdf"]', 'QUE SE REVISE Y MODIFIQUE EL ARTÍCULO 22 DE LA LEY GENERAL DE AGUAS NACIONALES, SE EXHORTA A PESIDENCIA DE MÉXICO, CONGRESO DE LA UNIÓN SENADO Y JUCOPO DE CONGRESO FEDERAL.', 'NA');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('4', 4, '', '', 'PROPOSICIÓN CON PUNTO DE ACUERDO; ÚNICO: EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA, MTRA. MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE A TRAVÉS DE SU SECRETARIO DE SALUD, DR. JOSÉ ADRIÁN MEDINA AMARILLAS, A EFECTO DE QUE INFORME EN RELACIÓN A LA ENFERMEDAD VÍRICA CONOCIDA COMO VIRUELA SÍMICA (MPOX), LAS ACCIONES DE PREVENCIÓN UE ESTÁN REALIZANDO PARA EVITAR CONTAGIOS; LAS ACCIONES QUE SE REALIZARÁN EN CASO DE CONFIRMARSE CASO POSITIVOS Y; LAS CAMPAÑAS DE INFORMACIÓN QUE ESTÁ PROMOVIENDO ANTE LOS BAJACALIFORNIANOS PARA MANTENERLOS CONOCEDORES DE LAS MEDIDAS DE PREVENCIÓN, LOS SIGNOS Y SÍNTOMAS DE LA ENFERMEDAD, ASÍ COMO LOS MEDIOS DE DIFUSIÓN DE DICHAS CAMPAÑAS.', 'NULL', '', '', 'NULL', 'PROPOSICION', 'NULL', 'NULL', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7606523451866275.pdf"]', 'INFORME EN RELACIÓN A LA ENFERMEDAD VÍRICA CONOCIDA COMO VIRUELA SÍMICA (MPOX), LAS ACCIONES DE PREVENCIÓN UE ESTÁN REALIZANDO PARA EVITAR CONTAGIOS; LAS ACCIONES QUE SE REALIZARÁN EN CASO DE CONFIRMARSE CASO POSITIVOS', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('28', 28, '', '', 'PRIMERO: “ESTA SOBERANÍA EXHORTE A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA MTRA. MARINA DEL PILAR ÁVILA OLMEDA Y A LA PRESIDENTA MUNICIPIO DE MEXICALI, BAJA CALIFORNIA MTRA. NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE POR CONDUCTO DE LOS RESPECTIVOS TITULARES DEL ESTADO Y MUNICIPIO DE PROTECCIÓN CIVIL, O DE QUIEN CONSIDEREN IDÓNEO, PRONUNCIEN REGLAS Y HORARIOS SEGUROS, PUNTOS SEGUROS, LO ANTERIOR PARA LA PRÁCTICA DEL SENDERISMO DURANTE LOS MESES DE JULIO, AGOSTO Y SEPTIEMBRE DEL PRESENTE AÑO, EN VIRTUD DEL RIESGO QUE REPRESENTA REALIZAR ESTA ACTIVIDAD ANTE LAS ALTAS TEMPERATURAS QUE SE REGISTRAN EN ESOS MESES EN ESTE MUNICIPIO. SEGUNDO: EN COORDINACIÓN CON LAS AUTORIDADES DE SEGURIDAD PÚBLICA ESTABLEZCAN VIGILANCIA PERMANENTE DURANTE ESOS MESES EN LOS CERROS EL CENTINELA, EL CIEMPIÉS, LA LAGUNA SALADA Y EL CERRO PRIETO, PARA EVITAR ACCIDENTES Y LAMENTABLES MUERTES EN LA PRÁCTICA DE ESTE SANO DEPORTE.TECERO: REFORZAR EL USO OBLIGATORIO DEL SISTEMA INTEGRAL DE REGISTRO DE ACTIVIDADES DE RIESGO EN ZONAS ABIERTAS, NO SOLO PARA EVENTOS ORGANIZADOS, SINO TAMBIÉN PROMOVIENDO SU USO ENTRE GRUPOS INFORMALES MEDIANTE CAMPAÑAS PÚBLICAS Y REDES SOCIALES.CUARTO: ESTABLECER UN HORARIO OFICIAL PARA LA PRÁCTICA DEL SENDERISMO EN VERANO, ESPECÍFICAMENTE DURANTE LOS MESES DE JULIO A SEPTIEMBRE; ASÍ MISMO, INSTALAR SEÑALAMIENTOS PREVENTIVOS DE ACCESOS.QUINTO: QUE EL DIRECTOR DE PROTECCIÓN CIVIL ESTATAL EN BAJA CALIFORNIA, JOSÉ SALVADOR CERVANTES HERNÁNDEZ, EN COORDINACIÓN CON EL DIRECTOR DE PROTECCIÓN CIVIL MUNICIPAL EN MEXICALI, RENÉ SALVADOR ROSADO, GENEREN A LA PAR UN PROTOCOLO DE PREVENCIÓN PARA LAS PERSONAS QUE REALIZAN EL SENDERISMO EN LA REGIÓN EN TEMPORADA DE CLIMA EXTREMO, CON ENFOQUE EN SEGURIDAD, MONITOREO Y PREVENCIÓN DE RIESGOS.', 'APROBADA', '', '', 'NULL', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6648843559399227.pdf"]', 'NULL', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.08619744551946618.pdf"]', 'PROTECCIÓN CIVIL DE GOB BC Y AYMNTO MXLI PUBLIQUEN REGLAS, HORARIOS Y PUNTOS SEGUROS PARA PRACTICAR SENDERISMO EN TEMPORADA DE VERANO; REFORZAR EL USO OBLIGATORIO DEL SISTEMA INTEGRAL DEL REGISTRO DE ACTIVIDADES DE RIESGO EN ZONAS ABIERTAS Y EN CONJUNTO CON SEGURIDAD PUBLICA ESTABLEZCAN VIGILANCIA PERMANENTE EN LOS CERROS: EL CENTINELA, EL CIEMPIÉS, LA LAGUNA SALADA Y EL CERRO PRIETO Y A LA PAR SE GENERE UN PROTOCOLO DE PREVENCIÓN  PARA LAS PERSONAS QUE REALIZAN SENDERISMO EN TEMPORADA DE CLIMA EXTREMO..', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('54', NULL, '2026-02-09', '2026-02-18', 'PRIMERO. LA H XXV LEGISLATURA DEL CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE AL TITULAR DE LA SECRETARÍA DE HACIENDA DEL ESTADO, EL C.P. JOSÉ ANDRÉS PULIDO SAAVEDRA, EN SU CARÁCTER DE SUPERIOR JERÁRQUICO DE LAS OFICINAS RECAUDADORAS DE RENTAS EN LOS MUNICIPIOS DEL ESTADO, PARA QUE, EN EL ÁMBITO DE SUS ATRIBUCIONES, INTRUYA Y GARANTICE QUE NO SE IMPIDA A LAS PERSONAS CONTRIBUYENTES REALIZAR EL PAGO DEL DERECHO DE RENOVACIÓN DE LA TARJETA DE CIRCULACIÓN VEHICULAR DEL EJERCICIO FISCAL CORRESPONDIENTE RESPECTO DEL VEHÍCULO QUE SE ENCUENTRE EN USO Y DEL CUAL SE PRETENDA CUMPLIR, AUN CUANDO EN LOS SISTEMAS EXISTAN REGISTROS DE MULTAS, RECARGOS O ADEUDOS RELACIONADOS CON OTROS VEHÍCULOS O CONCEPTOS DIVERSOS, A FIN DE EVITAR QUE DICHO BLOQUEO GENERE MULTAS Y RECARGOS ADICIONALES POR EXTERMPORANEIDAD; ASIMISMO, PARA QUE SE HABILITEN MECANISMOS CLAROS Y ACCESIBLES QUE PERMITAN AL CIUDADANO ACLARAR, REGULARIZAR O IMPUGNAR LOS ADEUDOS HISTÓRICOS SIN QUE ELLO SE CONVIERTA EN CONDICIÓN PARA EL PAGO DE LO VIGENTE, Y PARA QUE, DE OFICIO, SE REALICE LA REVISIÓN Y DEPURACIÓN DE MULTAS Y CRÉDITOS CUYA EXIGIBILIDAD SE ENCUENTRE EXTINTA POR PRESCRIPCIÓN, EVITANDO QUE CRÉDITOS JURÍDICAMENTE INEXIGIBLES SE MANTENGAN COMO CANDADOS ADMINISTRATIVOS. SEGUNDO. LA H. XXV LEGISLATURA DEL CONGRESO DEL ESTADO DE BAJA CALIFORNIA, EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DEL H. AYUNTAMIENTO DE MEXICALI, MTRA. NORMA ALICIA BUSTAMANTE MARTÍNEZ, EN SU CARÁCTER DE TITULAR DEL AYUNTAMIENTO Y SUPERIOR JERÁRQUICO DE LA TESORERÍA MUNICIPAL Y LA OFICINA RECAUDADORA DE RENTAS MUNICIPAL, PARA QUE GARANTICE QUE NO SE CONDICIONE NI SE BLOQUEE EL PAGO DEL IMPUESTO PREDIAL A LA LIQUIDACIÓN DE MULTAS  ADMINISTRATIVAS U OTROS CRÉDITOS DIVERSOS CARGADOS AL DOMICILIO EN LOS SISTEMAS DE RECUDACIÓN, PERMITIENDO QUE LA CIUDADANÍA CUBRA EN TIEMPO EL IMPUESTO PREDIAL, CONSERVE LOS DESCUENTOS APLICABLES Y EVITE RECARGOS POR EXTERMPORANEIDAD, SIN PERJUICIO DE QUE POSTERIORMENTE PUEDA PAGAR, ACLARAR O COMBATIR LEGALEMENTE LAS MULTAS QUE CORRESPONDAN; ASIMISMO, PARA QUE LA AUTORIDAD RECAUDADORA MUNICIPAL REALICE DE OFICIO LA REVISIÓN, DEPURACIÓN Y CANCELACIÓN DE MULTAS Y CRÉDITOS QUE LEGALEMENTE HAYAN PRESCRITO, A FIN DE QUE NO SE UTILICEN COMO OBSTÁCULOS PARA EL CUMPLIMIENTO OPORTUNO DEL PREDIAL NI SE MANTENGAN E LOS SISTEMAS DE COBROS QUE YA NO SON EXIGIBLES CONFORME A DERECHO.', 'APROBADA', '', '2026-02-24', 'PROPOSICIÓN PRESENTADO POR DIEGO ECHEVARRÍA Y MAYOLA GAONA SE ADIHERE JUNTO CON ALEJANDRINA CORRAL.', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6351920948616139.pdf"]', NULL, '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8510942225196209.pdf"]', 'QUE NO SE LIMITE EL PAGO DE PREDIAL Y REVALIDACIÓN DE TARJETA DE CIRCULACIÓN DEBIDO A ADEUDOS, MULTAS ETC. DE OTROS VEHÍCULOS O DE FALTAS ADMINISTRATIVAS', 'NA');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('39', 97, '2026-01-12', '2026-01-15', '"ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A MÓNICA VARGAS NÚÑEZ, SECRETARIA DE AGRICULTURA Y DESARROLLO RURAL DEL ESTADO DE BAJA CALIFORNIA; ASÍ COMO A JOSÉ ANDRÉS PULIDO SAAVEDRA, SECRETARIO DE HACIENDA DEL ESTADO DE BAJA CALIFORNIA; PARA QUE, EN EL ÁMBITO DE SUS RESPECTIVAS ATRIBUCIONES, ATIENDAN DE MANERA PRIORITARIA LA PROBLEMÁTICA QUE ENFRENTA EL CULTIVO DEL ALGODÓN EN EL VALLE DE MEXICALI; INSTALEN MECANISMOS DE ANÁLISIS Y SEGUIMIENTO CON PARTICIPACIÓN DE LOS PRODUCTORES; EVALÚEN LA VIABILIDAD DE IMPLEMENTAR APOYOS ECONÓMICOS EXTRAORDINARIOS POR HECTÁREA, PROPONIENDO LA CANTIDAD DE $7,000.00 (SIETE MIL PESOS 00/100 M.N.) POR HECTÁREA, BAJO REGLAS CLARAS, PADRONES VERIFICABLES Y CRITERIOS DE TRANSPARENCIA; ASÍ COMO QUE REALICEN LAS GESTIONES QUE RESULTEN NECESARIAS ANTE LAS INSTANCIAS FEDERALES COMPETENTES, CON EL OBJETO DE MITIGAR LAS PÉRDIDAS ECONÓMICAS, EVITAR UNA MAYOR REDUCCIÓN DE LA SUPERFICIE SEMBRADA Y PRESERVAR LA VIABILIDAD PRODUCTIVA DEL CULTIVO DEL ALGODÓN EN EL VALLE DE MEXICALI”', 'APROBADA', '', '2026-02-24', 'NULL', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.75595078810839.pdf"]', 'ACUERDO DISTRIBUIDOR VIAL LC-CARRANZA.pdf https://s3.us-west-2.amazonaws.com/storage-private.teable.io/table/2elnZGx3SWlu?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Content-Sha256=UNSIGNED-PAYLOAD&X-Amz-Credential=AKIAZOU4IL5VBK43V7CM%2F20260219%2Fus-west-2%2Fs3%2Faws4_request&X-Amz-Date=20260219T205454Z&X-Amz-Expires=518400&X-Amz-Signature=dd1a1621f1d2365a9266cba7759b6142357eea0961a994af6c89ffe3903fe994&X-Amz-SignedHeaders=host&response-content-disposition=attachment%3B%20filename%2A%3DUTF-8%27%27ACUERDO%2520DISTRIBUIDOR%2520VIAL%2520LC-CARRANZA.pdf&x-id=GetObject', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.3126527706354718.pdf"]', 'SE EXHORTA A GOBIERNO BC, SRIA AGRICULTURA Y SRIA. HACIENDA PARA GENERAR UN APOYO DE 7 MIL PESOS POR HECTAREA PARA COMPENSAR LA PERDIDA EN EL CULTIVO DE ALGODÓN.', 'NA');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('33', 63, '', '', '“ÚNICO: EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA SECRETARÍA DE AGRICULTURA Y DESARROLLO RURAL DEL ESTADO DE BAJA CALIFORNIA, A TRAVÉS DE SU TITULAR MÓNICA VARGAS NÚÑEZ; AL FIDEICOMISO FONDO DE GARANTÍAS COMPLEMENTARIAS Y CRÉDITOS PUENTE (FOGABAC), DIRIGIDO POR CARLOS ENRIQUE SILVA ROBLES, PARA QUE IMPLEMENTEN UN PROGRAMA INTEGRAL DE RECUPERACIÓN Y CONDONACIÓN JUSTA DE LA CARTERA VENCIDA, QUE REACTIVE EL CRÉDITO AGRÍCOLA Y GARANTICE QUE LOS RECURSOS DISPONIBLES SE TRADUZCAN EN FINANCIAMIENTO REAL Y RESULTADOS PRODUCTIVOS PARA LOS AGRICULTORES DEL VALLE DE MEXICALI; ASÍ COMO A LA SECRETARÍA DE HACIENDA DEL ESTADO DE BAJA CALIFORNIA, A CARGO DE SU TITULAR JOSÉ ANDRÉS PULIDO SAAVEDRA, PARA QUE REALICE LAS GESTIONES PRESUPUESTALES NECESARIAS QUE PERMITAN ASIGNAR Y GARANTIZAR LA SUFICIENCIA FINANCIERA DEL FOGABAC, FORTALECIENDO SU CAPACIDAD OPERATIVA Y ASEGURANDO LA CONTINUIDAD DE LOS CRÉDITOS AGRÍCOLAS EN BENEFICIO DEL SECTOR PRODUCTIVO DEL CAMPO.”, MISMO QUE TENDRÁ QUE REALIZARSE BAJO LOS SIGUIENTES PUNTOS:UNO. SE EXHORTA A LA SECRETARIA DE AGRICULTURA Y DESARROLLO RURAL, A SUPERVISAR Y ACOMPAÑAR LA EJECUCIÓN DEL PROGRAMA INTEGRAL DE RECUPERACIÓN 3 DE 3, CONDONACIÓN JUSTA DE LA CARTERA VENCIDA, QUE REACTIVEN EL CRÉDITO AGRÍCOLA Y CERTIFIQUEN QUE LOS RECURSOS DISPONIBLES SE TRADUZCAN EN FINANCIAMIENTO REAL, GARANTIZANDO TRANSPARENCIA, RENDICIÓN DE CUENTAS Y RESULTADOS TANGIBLES.DOS. SE SOLICITA AL FOGABAC, A PRESENTAR ANTE ESTE CONGRESO UN INFORME SEMESTRAL SOBRE LOS AVANCES Y RESULTADOS OBTENIDOS, INCLUYENDO LOS MONTOS RECUPERADOS MEDIANTE EL PROGRAMA 3 DE 3, LAS CONDONACIONES AUTORIZADAS Y LOS CRÉDITOS REACTIVADOS, A FIN DE GARANTIZAR QUE EL CRÉDITO AGRÍCOLA VUELVA A SER UNA REALIDAD PARA QUIENES MANTIENEN VIVA LA AGRICULTURA DE BAJA CALIFORNIA.TRES. SE EXHORTA AL FOGABAC A GARANTIZAR MÁXIMA TRANSPARENCIA PUBLICANDO EN SU PORTAL LOS LINEAMIENTOS Y CRITERIOS DEL PROGRAMA DE REESTRUCTURACIÓN, EL CALENDARIO DE EJECUCIÓN, LOS REPORTES DE GARANTÍAS LÍQUIDAS Y LOS CONVENIOS FIRMADOS CON DATOS ABIERTOS, EVITANDO CUALQUIER OPACIDAD U OCULTAMIENTO DE INFORMACIÓN PARA ASEGURAR QUE CADA PESO DESTINADO AL CRÉDITO AGRÍCOLA SE TRADUZCA EN APOYO REAL Y VERIFICABLE A QUIENES MANTIENEN VIVA LA AGRICULTURA DE BAJA CALIFORNIACUATRO. SE EXHORTA A LA SECRETARÍA DE HACIENDA DEL ESTADO DE BAJA CALIFORNIA, A CARGO DE SU TITULAR A SOLICITAR Y REALIZAR PARA EL PRESUPUESTO DE EGRESOS DE 2026, LA ASIGNACIÓN Y SUFICIENCIA PRESUPUESTAL QUE PERMITA FORTALECER LOS RECURSOS DEL FOGABAC Y GARANTIZAR LA OPERACIÓN DE LOS CRÉDITOS AGRÍCOLAS.', 'APROBADA', '', '', 'RESPUESTA 1SRIA AGRICULTURA, 2FOGABAC', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.05460703204742812.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8233193972937161.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.15439446103030163.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.2895137056112884.pdf"]', 'IMPLEMENTAR UN PROGRAMA DE RECUPERACIÓN Y CONDONACIÓN DE CARTERA VENCIDA DE FOGABAC; EJECUCIÓN DE UN PROGRAMA INTEGRAL 3 DE 3; INFORME SEMESTRAL DE AVANCES Y RESULTADOS OBTENIDOS; GARANTÍA DE MÁXIMA TRANSPARENCIA; NUEVA ESTRATEGIA PARA 2026 DE SANEAMIENTO Y REFORZAMIENTO DEL FOGABAC.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('57', NULL, '2026-02-23', '2026-02-26', '"ÚNICO: EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A MIRIAM ELIZABETH CANO NÚÑEZ, PRESIDENTA MUNICIPAL DEL MUNICIPIO DE SAN QUINTÍN, BAJA CALIFORNIA; A YVONNE BERENICE CARAM ALBA, OFICIALÍA MAYOR DEL MUNICIPIO DE SAN QUINTÍN; Y A CHRISTIAN HINOJOSA CHÁVEZ, DIRECTOR DE SEGURIDAD PÚBLICA MUNICIPAL; PARA QUE, POR CONDUCTO DE SUS RESPECTIVAS ÁREAS COMPETENTES, REALICEN UN ANÁLISIS E INFORME A ESTA SOBERANÍA, CUAL SERÁ RUTA TENDIENTE A QUE CESEN LAS RETENCIONES POR CONCEPTO DE IMPUESTO SOBRE LA RENTA APLICADAS A LOS AGENTES POLICIACOS EN RETIRO, CUANDO SUS PENSIONES SE ENCUENTREN DENTRO DEL SUPUESTO DE EXENCIÓN PREVISTO EN EL ARTÍCULO 93, FRACCIÓN IV, DE LA LEY DEL IMPUESTO SOBRE LA RENTA; REVISEN LOS DESCUENTOS YA PRACTICADOS EN TALES CASOS; Y, EN SU CASO, ADOPTEN LOS AJUSTES ADMINISTRATIVOS Y PROCEDAN A LA DEVOLUCIÓN DE LAS CANTIDADES INDEBIDAMENTE RETENIDAS, GARANTIZANDO EL ESTRICTO APEGO A LA LEGISLACIÓN FISCAL FEDERAL VIGENTE.”', 'APROBADA', '', '', 'LLEGÓ COPIA DE RECIBIDO DE LA SRIA. GRAL. DE GOB. COPIA ENVIADA POR LA PRESIDENTA DEL CONGRESO', 'PROPOSICION', NULL, '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.03189638522281879.pdf"]', NULL, '', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('59', NULL, '2026-03-10', '2026-03-12', 'A LA INICIATIVA CON PROYECTO DE DECRETO POR EL QUE  SE REFORMA EL ARTÍCULO 85 Y SE ADIIONAN LOS ARTÍCULOS 85 BIS Y TER DE LA LEY DE MOVILIDAD SUSTENTABLE Y TRANSPORTE DEL ESTADO DE BAJA CALIFORNIA', 'APROBADA', '', '', '', 'POSICIONAMIENTO', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.9087041514597272.pdf"]', NULL, NULL, '', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('61', NULL, '2026-03-23', '2026-03-23', '“ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DE SAN QUINTÍN, MIRIAM ELIZABETH CANO NÚÑEZ, AL PRIMER AYUNTAMIENTO DE SAN QUINTÍN, A TRAVÉS DE SU SECRETARIA DEL AYUNTAMIENTO, CLAUDIA IVETTE ESCAMILLA; ASÍ COMO AL SÍNDICO PROCURADOR DEL PRIMER AYUNTAMIENTO DE SAN QUINTÍN, JUAN PABLO GUERRERO GAMBOA; A TRANSPARENTAR EL RÉGIMEN JURÍDICO, PATRIMONIAL Y CONTRACTUAL DEL INMUEBLE QUE ACTUALMENTE FUNCIONA COMO SEDE DEL GOBIERNO MUNICIPAL, ASÍ COMO A RENDIR CUENTAS SOBRE EL ORIGEN, MONTO Y DESTINO DE LOS RECURSOS PÚBLICOS INVERTIDOS EN SU REMODELACIÓN Y ADECUACIÓN”.', 'APROBADA', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.02947669632416894.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8894978650661662.pdf"]', NULL, 'TRANSPARENTAR LA SITUACIÓN DE LA CASA EN DONDE DESPACHA LA PRESIDENTA MUNICIPAL EN SAN QUINTÍN, B.C.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('52', 227, '', '', '', 'APROBADA', '', '', 'NULL', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6216461384694435.pdf"]', 'NULL', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8122188357567852.pdf"]', 'SE INFORME DE MANERA PUNTUAL LA FORMA EN QUE SE ESTÁ INSTRUMENTANDO EN B.C. LA APLICACIÓN DE LAS ACTAS 323 Y 330, PARTICULARMENTE EN LO RELATIVO A LA REDUCCIÓN DE VOLÚMENES DE AGUA DEL RÍO COLORADO Y EL DESCANSO DE TIERRAS AGRÍCOLAS.', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('63', NULL, '2026-04-14', '2026-04-16', 'POSICIONAMIENTO REFERENTE A LA REDUCCIÓN DEL DERECHO AL AMPARA, A LA AMPLIACIÓN DE LOS DELITOS CON PRISIÓN PREVENTIVA Y LA ATRIBUCIÓN QUE SE LA DA A LA UNIDAD DE INTELIGENCIA FINANCIERA (UIF) PARA QUE PUEDA CONGELAR CUENTAS BANCARIAS SIN ORDEN JUDICIAL, SOLO POR "INDICIOS"', '', '', '', '', 'POSICIONAMIENTO', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.09211057174481108.pdf"]', NULL, NULL, '', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('60', NULL, '2026-03-23', '2026-03-23', '“ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE AL SECRETARIO DE AGRICULTURA Y DESARROLLO RURAL DEL GOBIERNO DE MÉXICO (SADER), JULIO BERDEGUÉ SACRISTÁN; A LA SECRETARIA DE DESARROLLO AGRARIO, TERRITORIAL Y URBANO DEL GOBIERNO DE MÉXICO (SEDATU), EDNA ELENA VEGA RANGEL; AL DIRECTOR EN JEFE DEL REGISTRO AGRARIO NACIONAL (RAN), LUIS CRUZ NIEVA; AL TITULAR DE LA PROCURADURÍA AGRARIA (PA), VÍCTOR SUÁREZ CARRERA; AL DIRECTOR GENERAL DEL INSTITUTO MEXICANO DEL SEGURO SOCIAL (IMSS), ZOÉ ROBLEDO ABURTO; AL DIRECTOR GENERAL DEL INSTITUTO DEL FONDO NACIONAL DE LA VIVIENDA PARA LOS TRABAJADORES (INFONAVIT), OCTAVIO ROMERO OROPEZA, ASÍ COMO AL JEFE DEL SERVICIO DE ADMINISTRACIÓN TRIBUTARIA (SAT), ANTONIO MARTÍNEZ DAGNINO; TODOS LOS ANTERIORES EN EL ORDEN FEDERAL; POR ÚLTIMO, AL SECRETARIO DEL TRABAJO Y PREVISIÓN SOCIAL DE BAJA CALIFORNIA, ALEJANDRO ARREGUI IBARRA; Y AL SECRETARIO DE ECONOMÍA E INNOVACIÓN (SEI) DE BAJA CALIFORNIA, KURT IGNACIO HONOLD MORALES, ESTO EN LA ESFERA ESTATAL; PARA QUE EN EL ÁMBITO DE SU COMPETENCIA ESTABLEZCAN OFICINAS DE ENLACE Y TRAMITOLOGÍA EN EL MUNICIPIO DE SAN QUINTÍN, BAJA CALIFORNIA” CON EL OBJETO DE FORTALECER EL DESARROLLO ECONÓMICO DE LA REGIÓN”', 'APROBADA', '', '', '', '', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8664443889735505.pdf"]', NULL, '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.26281357706760944.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7766574424933478.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.61825207026345.pdf"]', 'ESTABLECER OFICINAS DE DIVERSAS DEPENDENCIAS ESTATALES Y FEDERALES EN SAN QUINTÍN', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('58', NULL, '2026-03-13', '2026-03-12', '“ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA HACE UN ATENTO Y RESPETUOSO EXHORTO AL SECRETARIO DE HACIENDA DE BAJA CALIFORNIA, JOSÉ ANDRÉS PULIDO SAAVEDRA; Y AL SECRETARIO DE ECONOMÍA E INNOVACIÓN DE BAJA CALIFORNIA, KURT IGNACIO HONOLD MORALES, PARA QUE, A TRAVÉS DE LAS INSTANCIAS PERTINENTES, SE BUSQUEN RECURSOS ECONÓMICOS DESTINADOS A LA CREACIÓN DE NUEVOS PROGRAMAS DE APOYO FINANCIERO PARA EL EMPRENDIMIENTO FEMENINO. ESTOS PROGRAMAS DEBERÍAN INCLUIR NO SOLO UNA INVERSIÓN INICIAL, SINO TAMBIÉN ASISTENCIA ECONÓMICA, ASESORÍA, MENTORÍA, APOYO TÉCNICO Y CAPACITACIÓN CONSTANTE EN LAS ETAPAS POSTERIORES, CON EL OBJETIVO DE PROMOVER UN EMPRENDIMIENTO SOSTENIBLE Y EXITOSO ENTRE LAS MUJERES DE NUESTRO ESTADO.”', 'APROBADA', '', '', 'LA FECHA DE ENTRADA A PARLAMENTARIOS ES POSTERIOR PORQUE SE HIZO UNA ADECUACIÓN DESPUÉS DEL PLENO', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.4333885476730871.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.08577219103253964.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.2252744833226158.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.026348474907616937.pdf"]', 'SE CREEN NUEVOS PROGRAMAS Y SE FORTALEZCAN LOS YA EXISTENTES EN REACIÓN AL EMPRENDIMIENTO FEMENINO', 'NULL');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('77', NULL, '2026-08-10', '2026-08-27', '“ÚNICO. EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A GERARDO SANTIAGO RUIZ, GERENTE DIVISIONAL DE DISTRIBUCIÓN DE LA CFE EN BAJA CALIFORNIA, PARA QUE EN EL ÁMBITO DE SU COMPETENCIA REALICE LAS GESTIONES NECESARIAS PARA EVITAR LA EMISIÓN DE COBRO DE LOS LLAMADOS RECIBOS LOCOS; EL CORTE DE ENERGÍA ELÉCTRICA DURANTE LOS MESES QUE DURA EL SUBISIDIO FEDERAL, ESTO ES DE MAYO A OCTUBRE DE 2026, A LAS PERSONAS DEUDORAS QUE COMPRUEBEN FEHACIENTEMENTE ENCONTRARSE ENTRE EL GRUPO DE PERSONAS EN ESTADO DE VULNERABILIDAD; ASÍ COMO EVITAR EN LA MEDIDA DE LO POSIBLE, LOS APAGONES MÁXIME EN LA HORA PICO COMO HAN ESTADO SUSCEDIENDO, DAÑANDO LOS APARATOS DOMÉSTICOS, ADEMÁS DEL SUFRIMIENTO DE LA CIUDADANÍA POR LA FALTA DE ENERGÍA ELÉCTRICA TODO ELLO EN EL MUNICIPIO DE MEXICALI BAJA CALIFORNIA".', 'APROBADA', '2026-08-14', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.44474808478470484.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.95464098395972.pdf"]', NULL, 'EVITAR COBRO DE RECIBOS LOCOS, CORTES POR FALTA DE PAGO DURANTE EL SUBSIDIO FEDERAL Y MINIMIZAR APAGONES', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('64', NULL, '2026-04-21', '2026-04-23', '“ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA; A BIEN DE GARANTIZAR EL SEGUIMIENTO OPORTUNO DE LAS QUEJAS CIUDADANAS, LA EMISIÓN DE RECOMENDACIONES EN TIEMPO Y FORMA, Y EL CUMPLIMIENTO EFECTIVO DE LAS MISMAS”, AL TENOR DE LOS SIGUIENTES PUNTOS:  UNO. LA XXV LEGISLATURA DEL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA, A FORTALECER EL SEGUIMIENTO A LAS QUEJAS CIUDADANAS, GARANTIZAR INFORMACIÓN OPORTUNA A CADA QUEJOSO Y EMITIR EN LOS PLAZOS DE LEY TODAS LAS RECOMENDACIONES PENDIENTES, PRIORIZANDO EXPEDIENTES DE VÍCTIMAS EN SITUACIÓN DE VULNERABILIDAD.  DOS. LA XXV LEGISLATURA DEL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA, A REMITIR A LA PRESIDENCIA DE LA MESA DIRECTIVA, EN UN PLAZO MÁXIMO DE TREINTA DÍAS HÁBILES, UN INFORME SOBRE EL ESTADO DE CUMPLIMIENTO DE TODAS SUS RECOMENDACIONES VIGENTES DESDE SU NACIMIENTO EN 2015 Y HASTA LA FECHA DE RECEPCIÓN DE ESTE PUNTO DE ACUERDO, IDENTIFICANDO AUTORIDADES DESTINATARIAS, GRADO DE ACATAMIENTO Y MEDIDAS ADOPTADAS ANTE EL PROBABLE INCUMPLIMIENTO.', '', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6100640490745011.pdf"]', NULL, NULL, 'GARANTIZAR EL SEGUIMIENTO OPORTUNO DE LAS QUEJAS CIUDADANAS, LA EMISIÓN DE RECOMENDACIONES Y EL CUMPLIMIENTO EFECTIVO DE LAS MISMAS.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('65', NULL, '2026-04-21', '2026-04-23', 'ÚNICO: “EL PODER LEGISLATIVO DEL ESTADO DE BAJA CALIFORNIA EXHORTA A JORGE ALBERTO GUTIÉRREZ TOPETE, TITULAR DEL INSTITUTO DE MOVILIDAD SUSTENTABLE (IMOS); A NORMA ALICIA BUSTAMANTE MARTÍNEZ, PRESIDENTA MUNICIPAL DE MEXICALI PARA QUE EN EL ÁMBITO DE SUS RESPECTIVAS COMPETENCIAS, IMPLEMENTEN ACCIONES INMEDIATAS Y COORDINADAS A EFECTO DE IMPLEMENTAR UN PROGRAMA EMERGENTE DE REHABILITACIÓN, MANTENIMIENTO E INSTALACIÓN DE PARADAS DE TRANSPORTE PÚBLICO EN EL MUNICIPIO DE MEXICALI, GARANTIZANDO CONDICIONES ADECUADAS DE SEGURIDAD, FUNCIONALIDAD Y PROTECCIÓN FRENTE A LAS CONDICIONES CLIMÁTICAS Y DE INSEGURIDAD EN LA CIUDAD DE MEXICALI, BAJA CALIFORNIA.”', '', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.13636788854265847.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.5502971509199845.pdf"]', NULL, 'LOGRAR QUE LOS PARADEROS DE TRANSPORTE  PÚBLICO ADEMÁS DE SER FUNCIONALES PARA SU USO POR LA CIUDADANÍA, SEAN ADEMÁS PUNTOS SEGUROS', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('66', NULL, '2026-05-05', '2026-05-07', '“ÚNICO. EL CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A DIVERSAS AUTORIDADES FEDERALES Y ESTATALES COMPETENTES EN MATERIA HÍDRICA Y AGRÍCOLA, PARA GARANTIZAR QUE LOS 22 MÓDULOS DE RIEGO DEL DISTRITO DE RIEGO 014 RÍO COLORADO EN BAJA CALIFORNIA OPEREN CON TRANSPARENCIA EN EL MANEJO DE SUS RECURSOS, EN LOS PROCESOS INTERNOS DE ELECCIÓN DE MESAS DIRECTIVAS, PRESENTAR LA RENDICIÓN DE CUENTAS RESPALDADAS INSTITUCIONALMENTE, ASÍ COMO CONTAR CON UN MARCO NORMATIVO UNIFORME QUE PROTEJA LOS DERECHOS DE LOS PRODUCTORES AGRÍCOLAS QUE LOS INTEGRAN”.', 'APROBADA', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.3766691382743985.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8634891022933339.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6157528800415688.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.09648227124706887.pdf"]', 'GARANTIZAR LA REGULACIÓN Y RENDICIÓN DE CUENTAS EN TODOS LOS MÓDULOS DE RIEGO DEL DISTRITO 014 DEL VALLE DE MEXICALI', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('68', NULL, '', '', '', '', '', '', '', 'PROPOSICION', NULL, NULL, NULL, 'SE DE A CONOCER LA DISTRIBUCIÓN DEL RECURSO CORRESPONDIENTE  AL FONDO DE FOMENTO MUNICIPAL QUE TRANSFIERE LA SECRETARÍA DE HACIENDA Y CRÉDITO PÚBLICO MENSUALMENTE, ASÍ COMO EL DESTINO QUE LE DEN CADA UNO DE LOS AYUNTAMIENTOS DE BC', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('69', NULL, '2026-05-19', '2026-05-21', '', 'APROBADA', '', '', '', 'PROPOSICION', NULL, '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.12141769882234232.pdf"]', NULL, '', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('70', NULL, '2026-06-02', '2026-06-04', '“ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA; A BIEN DE GARANTIZAR EL SEGUIMIENTO OPORTUNO DE LAS QUEJAS CIUDADANAS, LA EMISIÓN DE RECOMENDACIONES EN TIEMPO Y FORMA, Y EL CUMPLIMIENTO EFECTIVO DE LAS MISMAS”, AL TENOR DE LOS SIGUIENTES PUNTOS: UNO. LA XXV LEGISLATURA DEL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA, A FORTALECER EL SEGUIMIENTO A LAS QUEJAS CIUDADANAS, GARANTIZAR INFORMACIÓN OPORTUNA A CADA QUEJOSO Y EMITIR EN LOS PLAZOS DE LEY TODAS LAS RECOMENDACIONES PENDIENTES, PRIORIZANDO EXPEDIENTES DE VÍCTIMAS EN SITUACIÓN DE VULNERABILIDAD. DOS. LA XXV LEGISLATURA DEL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA, A REMITIR A LA PRESIDENCIA DE LA MESA DIRECTIVA, EN UN PLAZO MÁXIMO DE TREINTA DÍAS HÁBILES, UN INFORME SOBRE EL ESTADO DE CUMPLIMIENTO DE TODAS SUS RECOMENDACIONES VIGENTES DESDE SU NACIMIENTO EN 2015 Y HASTA LA FECHA DE RECEPCIÓN DE ESTE PUNTO DE ACUERDO, IDENTIFICANDO AUTORIDADES DESTINATARIAS, GRADO DE ACATAMIENTO Y MEDIDAS ADOPTADAS ANTE EL PROBABLE INCUMPLIMIENTO.', 'APROBADA', '2026-06-05', '', '', 'PROPOSICION', NULL, '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.9482925903698933.pdf"]', NULL, 'GARANTIZAR EL SEGUIMIENTO OPORTUNO DE LAS QUEJAS CIUDADANAS, LA EMISIÓN DE RECOMENDACIONES Y EL CUMPLIMIENTO EFECTIVO DE LAS MISMAS.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('71', NULL, '2026-06-02', '2026-06-04', '“ÚNICO. EL HONORABLE CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JORGE ÁLVARO OCHOA ORDUÑO, PRESIDENTE DE LA COMISIÓN ESTATAL DE LOS DERECHOS HUMANOS DE BAJA CALIFORNIA; A BIEN DE GARANTIZAR EL SEGUIMIENTO OPORTUNO DE LAS QUEJAS CIUDADANAS, LA EMISIÓN DE RECOMENDACIONES EN TIEMPO Y FORMA, Y EL CUMPLIMIENTO EFECTIVO DE LAS MISMAS”', 'APROBADA', '2026-06-05', '', '', '', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.02730978152786967.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8088095268952608.pdf"]', NULL, 'GARANTIZAR EL SEGUIMIENTO OPORTUNO DE LAS QUEJAS CIUDADANAS, LA EMISIÓN DE RECOMENDACIONES Y EL CUMPLIMIENTO EFECTIVO DE LAS MISMAS.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('72', NULL, '2026-06-02', '2026-06-04', '“ÚNICO. LA XXV LEGISLATURA DEL CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA GOBERNADORA CONSTITUCIONAL DEL ESTADO DE BAJA CALIFORNIA, MARINA DEL PILAR ÁVILA OLMEDA; ASÍ COMO AL SECRETARIO DE SALUD DEL ESTADO, JOSÉ ADRIÁN MEDINA AMARILLAS, PARA QUE DEN INICIO CON LAS GESTIONES NECESARIAS ANTE EL GOBIERNO FEDERAL Y DESINCORPORARSE DEL CONVENIO DE FEDERALIZACIÓN DE LOS SERVICIOS DE SALUD SUSCRITO CON EL ORGANISMO PÚBLICO DESCENTRALIZADO IMSS BIENESTAR, PARA RETOMAR LA RECTORÍA ESTATAL DIRECTA DE LOS SERVICIOS DE SALUD EN BAJA CALIFORNIA, TOMANDO COMO REFERENTE LOS OCHO ESTADOS QUE PRESERVARON SU AUTONOMÍA EN LA MATERIA Y QUE HOY REPORTAN MEJORES INDICADORES DE ABASTO DE MEDICAMENTOS, INFRAESTRUCTURA HOSPITALARIA Y ATENCIÓN A LA POBLACIÓN”', 'APROBADA', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.799668962705366.pdf"]', NULL, NULL, 'REALIZAR LOS TRAMITES NECESARIOS PARA LLEVAR A CABO LA DESFEDERALIZACIÓN DE LOS SERVICIOS DE SALUD EN EL ESTADO DE BAJA CALIFORNIA, LO ANTERIOR PARA BENEFICIO DE LA POBLACIÓN BACALAFORNIANA.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('67', NULL, '2026-05-05', '2026-05-07', 'ÚNICO: EL PODER LEGISLATIVO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A IRMA MARTÍNEZ MANRÍQUEZ, SECRETARÍA DE EDUCACIÓN DEL ESTADO DE BAJA CALIFORNIA; AL GRAL. BRIGADIER E.M. LAUREANO CARRILLO RODRÍGUEZ, SECRETARIO DE SEGURIDAD CIUDADANA DEL ESTADO DE BAJA CALIFORNIA; Y A LUIS FELIPE CHAN BALTAZAR, DIRECTOR DE SEGURIDAD PÚBLICA MUNICIPAL DE MEXICALI, BAJA CALIFORNIA, PARA QUE, IMPLEMENTEN DE MANERA URGENTE Y COORDINADA UNA ESTRATEGIA INTEGRAL DE SEGURIDAD ESCOLAR QUE CONTEMPLE LAS SIGUIENTES ACCIONES PRIORITARIAS: 1.	LA INSTALACIÓN DE MESAS DE TRABAJO INTERINSTITUCIONALES PERMANENTES, CON LA PARTICIPACIÓN DE DIRECTIVOS, ASOCIACIONES DE PADRES DE FAMILIA Y EL PERSONAL DEL PROGRAMA D.A.R.E., A FIN DE DIAGNOSTICAR Y ATENDER DE FONDO LA VIOLENCIA EN LOS PLANTELES ESCOLARES. 2.	EL REFORZAMIENTO DE LA VIGILANCIA Y LOS PATRULLAJES PREVENTIVOS EN LOS ACCESOS DE LAS ESCUELAS EN HORARIOS DE ENTRADA Y SALIDA, ASÍ COMO LA CAPACITACIÓN AL PERSONAL ESCOLAR PARA LA SUPERVISIÓN DE ÁREAS COMUNES. 3.	EL REFUERZO DEL PROGRAMA D.A.R.E. EN AQUELLAS ZONAS GEOGRÁFICAS DE LA CIUDAD CON MAYOR INCIDENCIA DELICTIVA.”', 'APROBADA', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8144575039948675.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.23425650904471695.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.48678527072510613.pdf"]', 'LOGRAR UNA ESTRECHA VINCULACIÓN EN LOS TRABAJOS EN BENEFICIO DE LA COMUNIDAD ESTUDIANTIL EN RELACIÓN CON LA SEGURIDAD DENTRO DE LAS INSTITUCIONES ESCOLARES.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('74', NULL, '2026-06-16', '2026-06-18', '“ÚNICO. EL H. CONGRESO DEL ESTADO, EMITE UN ATENTO Y RESPETUOSO EXHORTO A LA PRESIDENTA MUNICIPAL DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE INSTRUYA DE MANERA INMEDIATA LA LIMPIEZA, REHABILITACIÓN Y MANTENIMIENTO INTEGRAL DE LAS UNIDADES DEPORTIVAS MUNICIPALES, CON ATENCIÓN PRIORITARIA AL', '', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.3086955603410285.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6150189214666366.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.08698476398483235.pdf"]', NULL, 'GARANTIZAR LA LIMPIEZA, REHABILITACIÓN Y MANTENIMIENTO INTEGRAL DE LAS UNIDADES DEPORTIVAS MUNICIPALES, ASÍ COMO GARANTIZAR QUE SUS INSTALACIONES SEAN DIGNAS, FUNCIONALES Y SEGURAS PARA LA COMUNIDAD.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('75', NULL, '2026-06-29', '2026-07-02', '“ÚNICO. EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A JESÚS ANTONIO ESTEVA MEDINA, SECRETARIO DE INFRAESTRUCTURA, COMUNICACIONES Y TRANSPORTES; A ENRIQUE SYDNEY CARAVEO ACOSTA, DELEGADO Y DIRECTOR GENERAL DEL CENTRO SICT DE LA SECRETARÍA DE INFRAESTRUCTURA, COMUNICACIONES Y TRANSPORTES EN BAJA CALIFORNIA; ASÍ COMO A ALEJANDRO SVARCH PÉREZ, DIRECTOR GENERAL DEL IMSS-BIENESTAR; Y A MIGUEL BERNARDO ROMERO FLORES, COORDINADOR FEDERAL DEL IMSS-BIENESTAR EN BAJA CALIFORNIA”, EN RAZÓN DE LOS SIGUIENTES INCISOS: A) LA XXV LEGISLATURA DEL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE AL TITULAR DE LA SECRETARÍA DE INFRAESTRUCTURA, COMUNICACIONES Y TRANSPORTES DEL GOBIERNO FEDERAL, JESÚS ANTONIO ESTEVA MEDINA, Y AL DIRECTOR GENERAL DEL CENTRO SICT BAJA CALIFORNIA, ENRIQUE SYDNEY CARAVEO ACOSTA, A QUE IMPLEMENTEN CON CARÁCTER URGENTE ACCIONES DE SEÑALIZACIÓN Y REHABILITACIÓN EN LOS TRAMOS CARRETEROS DE MAYOR SINIESTRALIDAD EN EL MUNICIPIO DE SAN QUINTÍN, PARTICULARMENTE EN LAS RUTAS DE ACCESO A COMUNIDADES RURALES Y EN LOS CORREDORES DE LA CARRETERA FEDERAL NÚMERO 1, E INFORMEN A ESTA SOBERANÍA EN UN PLAZO NO MAYOR A TREINTA DÍAS NATURALES SOBRE LAS ACCIONES PROGRAMADAS Y LOS RECURSOS DESTINADOS PARA TAL EFECTO, NO SOLO EN ESA MUNICIPALIDAD, TAMBIÉN EN TODO NUESTRO ESTADO, QUE SE INCLUYAN CADA UNO DE LOS SIETE MUNICIPIOS. B). LA XXV LEGISLATURA DEL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A ALEJANDRO SVARCH PÉREZ, DIRECTOR GENERAL DEL IMSS-BIENESTAR; Y A MIGUEL BERNARDO ROMERO FLORES, COORDINADOR FEDERAL DEL IMSS-BIENESTAR EN BAJA CALIFORNIA, A QUE INFORMEN A ESTA SOBERANÍA EN UN PLAZO NO MAYOR A TREINTA DÍAS NATURALES SOBRE EL ESTADO ACTUAL DEL EQUIPAMIENTO MÉDICO, LA DISPONIBILIDAD DE INSUMOS, LA PLANTILLA DE ESPECIALISTAS Y LA CAPACIDAD DE TRASLADO EN AMBULANCIA DE TODOS Y CADA UNO DE LAS CLÍNICAS Y HOSPITALES QUE SE ENCUENTRAN DENTRO DEL ESTADO DE BAJA CALIFORNIA, ASÍ COMO LAS MEDIDAS INMEDIATAS ADOPTADAS PARA GARANTIZAR LA ATENCIÓN OPORTUNA DE EMERGENCIAS EN ESTA REGIÓN DEL PAÍS.', 'APROBADA', '2026-07-06', '', 'TODOS LOS DOCUMENTOS FEDERALES FUERON RECIBIDOS EN LA SECRETARÍA GENERAL DE GOBIERNO', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7019518248216727.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.4063376721025458.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7657550833465472.pdf"]', 'IMPLEMENTAR CON CARÁCTER URGENTE ACCIONES DE SEÑANIZACIÓN Y REHABILITACIÓN EN LOS TRAMOS CARRETEROS DE MAYOR SINIESTRALIDAD EN EL MUNICIÍO DE SAN QUINTÍN, ASÍ COMO QUE SE INFORME AL ESTADO ACTUAL DEL EQUIPAMIENTO MÉDICO, A DESPONIBILIDAD DE INSUMOS, LA PLANILLA DE ESPECIALISTAS Y LA CAPACIDAD DE TRASLADO EN AMBULANCIA DE CADA UNO DE LOS HOSPITALES DE NUESTRO ESTADO', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('62', NULL, '2026-04-14', '2026-04-16', 'ÚNICO: “EL PODER LEGISLATIVO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A ROCÍO ADAME MUÑOZ, PRESIDENTA MUNICIPAL DE PLAYAS DE ROSARITO, BAJA CALIFORNIA; A ADRIÁN MEDINA AMARILLAS, SECRETARIO DE SALUD DEL ESTADO; A JUAN JOSÉ PON MÉNDEZ, SECRETARIO GENERAL DE GOBIERNO; Y A DIANA ASUNCIÓN PÉREZ ÁLVAREZ, DIRECTORA GENERAL DEL SISTEMA PARA EL DESARROLLO INTEGRAL DE LA FAMILIA DE BAJA CALIFORNIA (DIF), EN LOS SIGUIENTES TÉRMINOS: A)	SE EXHORTA RESPETUOSAMENTE A ROCÍO ADAME MUÑOZ, PRESIDENTA MUNICIPAL DE PLAYAS DE ROSARITO, BAJA CALIFORNIA, A EFECTO DE QUE SE AUTORICE QUE EN EL EDIFICIO DONDE ACTUALMENTE SE ENCUENTRA EL CENTRO COMUNITARIO DEL PARQUE GABRIEL ESQUIVEL UBICADO EN BOULEVARD GUERRERO ESQUINA CON C. BALBINO OBESA DE LA COLONIA LUCIO BLANCO, SE DESTINE PARA QUE FUNCIONES EL CENTRO DE DIAGNÓSTICO DE AUTISMO DEL MUNICIPIO PLAYAS DE ROSARITO; B)	SE EXHORTA RESPETUOSAMENTE A ADRIÁN MEDINA AMARILLAS, SECRETARIO DE SALUD DEL ESTADO PARA QUE EN EL ÁMBITO DE SUS ATRIBUCIONES, DESTINE PERSONAL MÉDICO CAPACITADO A EFECTO DE LOGRAR LA CREACIÓN Y FUNCIONAMIENTO DEL CENTRO DE DIAGNÓSTICO DE AUTISMO DEL MUNICIPIO PLAYAS DE ROSARITO, MISMO QUE DEBERÁ INCLUIR, UN EQUIPO MÉDICO MULTIDISCIPLINARIO QUE DE MANERA ENUNCIATIVA INCLUYENDO, NEUROPEDIATRA, PSICÓLOGO INFANTIL, TERAPEUTA DE LENGUAJE, TERAPEUTA FÍSICO, ESTO ES, QUE CUENTE CON TODO EL EQUIPO E INSTALACIONES NECESARIAS PARA EL DIAGNÓSTICO Y ATENCIÓN OPORTUNA DE LOS NIÑOS Y NIÑAS DIAGNOSTICADOS DENTRO DEL ESPECTRO AUTISTA; C)	SE EXHORTA RESPETUOSAMENTE A JUAN JOSÉ PON MÉNDEZ, SECRETARIO GENERAL DE GOBIERNO, PARA QUE EN EL ÁMBITO DE SUS ATRIBUCIONES Y DE FORMA VINCULADA REALICE LAS ACCIONES NECESARIAS CON LAS DIVERSAS AUTORIDADES ESTATALES Y MUNICIPALES, A EFECTO DE LOGRAR LA CREACIÓN Y FUNCIONAMIENTO DEL CENTRO DE DIAGNÓSTICO DE AUTISMO DEL MUNICIPIO PLAYAS DE ROSARITO; D)	SE EXHORTA RESPETUOSAMENTE A DIANA ASUNCIÓN PÉREZ ÁLVAREZ, DIRECTORA GENERAL DEL SISTEMA PARA EL DESARROLLO INTEGRAL DE LA FAMILIA DE BAJA CALIFORNIA (DIF), PARA QUE EN EL ÁMBITO DE SUS ATRIBUCIONES, DESTINE PERSONAL CAPACITADO A EFECTO DE LOGRAR LA CREACIÓN Y FUNCIONAMIENTO DEL CENTRO DE DIAGNÓSTICO DE AUTISMO DEL MUNICIPIO PLAYAS DE ROSARITO, EL CUAL DEBERÁ INCLUIR, TERAPEUTA DE LENGUAJE, TERAPEUTA FÍSICO, ESTO ES, QUE CUENTE CON TODO EL EQUIPO E INSTALACIONES NECESARIAS PARA EL DIAGNÓSTICO Y ATENCIÓN OPORTUNA DE LOS NIÑOS Y NIÑAS DIAGNOSTICADOS DENTRO DEL ESPECTRO AUTISTA.', '', '', '', 'TAMBIEN LLEGÓ EL ACUSE DE RECIBO DE DIF', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7117164874927664.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.41172094739605036.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8345272735697448.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.48609328523552187.pdf"]', 'LOGRAR LA CREACIÓN Y FUNCIONAMIENTO DEL CENTRO DE DIAGNÓSTICO DE AUTISMO DEL MUNICIPIO DE PALAYAS DE ROSARITO', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('73', NULL, '', '', '“ÚNICO. EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A EFRAÍN MORALES LÓPEZ, DIRECTOR GENERAL DE LA COMISIÓN NACIONAL DEL AGUA; Y A MANUEL GUERRERO LUNA, DIRECTOR DEL ORGANISMO DE CUENCA PENÍNSULA DE BAJA CALIFORNIA DE LA COMISIÓN NACIONAL DEL AGUA, PARA QUE EN EL ÁMBITO DE SUS RESPECTIVAS COMPETENCIAS Y ATRIBUCIONES EMITAN LAS INSTRUCCIONES NECESARIAS A EFECTO DE QUE LA ASOCIACIÓN CIVIL DENOMINADA USUARIOS DEFENSORES DEL AGUA DEL RÍO COLORADO EN EL VALLE DE MEXICALI, A.C. (ADURC), SEA ADMITIDA COMO PARTICIPANTE CON VOZ PERO SIN VOTO, EN LAS REUNIONES DEL COMITÉ HIDRÁULICO DEL DISTRITO DE RIEGO 014 RÍO COLORADO, EN ESPECIAL EN LAS QUE SE ABORDE EL PROGRAMA DE DESCANSO DE TIERRAS 2026; INSTRUYENDO PARA ESOS EFECTOS A JORGE ALEJANDRO LOMELÍ OSUNA, INGENIERO EN JEFE DEL DISTRITO DE RIEGO 014 RIO COLORADO, BAJA CALIFORNIA Y SONORA Y PRESIDENTE DEL COMITÉ HIDRÁULICO DEL DISTRITO DE RIEGO 014; A JUAN CARLOS FIERRO YÁÑEZ, PRESIDENTE DEL CONSEJO DIRECTIVO DEL DISTRITO DE RIEGO RÍO COLORADO, S. DE R.L. DE I.P. DE C.V.; ASÍ COMO A ENRIQUE MARTÍNEZ FLORES, GERENTE DEL DISTRITO DE RIEGO RÍO COLORADO, S. DE R.L. DE I.P. DE C.V.; PARA CON ELLO DAR TRÁMITE FAVORABLE A DICHA SOLICITUD Y TRANSPARENTAR ANTE LOS USUARIOS DE LOS 22 MÓDULOS DE RIEGO DEL DISTRITO DE RIEGO AL QUE SE HACE REFERENCIA, LAS BASES, LAS ACTAS, ACUERDOS Y AVANCES DEL PROGRAMA; GARANTIZANDO ASÍ EL DERECHO A LA PARTICIPACIÓN CIUDADANA EN LA ADMINISTRACIÓN DE LOS RECURSOS DEL ACTA 330 DE LA COMISIÓN INTERNACIONAL DE LÍMITES Y AGUAS (CILA)', '', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8975025717510678.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.041735020206061235.pdf"]', NULL, 'PERMITIR QUE LA ASOCIACIÓN CIVIL DENOMINADA USUARIOS DEFENSORES DEL AGUA DEL RÍO COLORADO EN EL VALLE DE MEXICALI, A.C., SEA ADMITIDA COMO PARTICIPANTE CON VOZ, PERO SIN VOTO, EN LAS REUNIONES DEL COMITÉ HIDRÁULICO DEL DISTRITO DE RIEGO 014 RÍO COLORADO, EN ESPECIAL EN LAS QUE SE ABORDE EL PROGRAMA DE DESCANSO DE TIERRAS 2026', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('79', NULL, '2026-08-11', '2026-08-13', 'PRIMERO. LA H. XXV LEGISLATURA DEL CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA TITULAR DEL PODER EJECUTIVO DEL ESTADO, MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE INSTRUYA A LAS SECRETARÍAS DE HACIENDA, DE SALUD Y DE INFRAESTRUCTURA, DESARROLLO URBANO Y REORDENACIÓN TERRITORIAL, A REALIZAR DE MANERA COORDINADA UN ESTUDIO TÉCNICO Y DE VIABILIDAD FINANCIERA PARA CONSTRUIR UNA NUEVA SEDE Y REUBICAR AL PERSONAL DE LA JURISDICCIÓN SANITARIA DE MEXICALI. SE SOLICITA QUE LOS RESULTADOS Y LA RUTA DE ATENCIÓN SEAN INFORMADOS A ESTE CONGRESO. SEGUNDO. LA H. XXV LEGISLATURA DEL CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA PRESIDENTA MUNICIPAL DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ, PARA QUE INSTRUYA A LA DIRECCIÓN DEL HEROICO CUERPO DE BOMBEROS DE MEXICALI A REALIZAR, A LA BREVEDAD POSIBLE, UNA INSPECCIÓN Y UN ESTUDIO TÉCNICO DE SEGURIDAD CONTRA INCENDIOS EN LAS INSTALACIONES ACTUALES DE LA JURISDICCIÓN SANITARIA DE MEXICALI, EN EL QUE SE REVISE, POR LO MENOS, LA CANTIDAD DE PERSONAS QUE PUEDE OCUPAR EL INMUEBLE DE MANERA SEGURA; LAS RUTAS Y SALIDAS DE EMERGENCIA; LA SEÑALIZACIÓN Y EL ALUMBRADO DE EMERGENCIA; LOS EXTINTORES, ALARMAS, DETECTORES, HIDRANTES Y DEMÁS EQUIPO CONTRA INCENDIOS. ASIMISMO, SE SOLICITA QUE EMITA LAS MEDIDAS URGENTES QUE DEBAN CUMPLIRSE Y REMITA LOS RESULTADOS A ESTE CONGRESO. TERCERO. LA H. XXV LEGISLATURA DEL CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LA TITULAR DEL PODER EJECUTIVO DEL ESTADO, MARINA DEL PILAR ÁVILA OLMEDA, PARA QUE INSTRUYA A LA COORDINACIÓN ESTATAL DE PROTECCIÓN CIVIL A REALIZAR, DENTRO DE SU ÁMBITO DE COMPETENCIA Y CON EL APOYO DE LAS UNIDADES TÉCNICAS QUE CORRESPONDAN, UNA INSPECCIÓN Y UN DICTAMEN TÉCNICO INMEDIATO SOBRE LAS INSTALACIONES ACTUALES DE LA JURISDICCIÓN SANITARIA DE MEXICALI. DICHO DICTAMEN DEBERÁ REVISAR, POR LO MENOS, EL ESTADO GENERAL Y ESTRUCTURAL DEL INMUEBLE; LAS INSTALACIONES ELÉCTRICAS; LA CANTIDAD SEGURA DE OCUPANTES; LAS RUTAS DE EVACUACIÓN; EL PROGRAMA INTERNO DE PROTECCIÓN CIVIL; LAS BRIGADAS Y EL EQUIPO DE EMERGENCIA; ASÍ COMO LAS CONDICIONES DEL ÁREA UTILIZADA PARA ALMACENAR MEDICAMENTOS E INSUMOS. TAMBIÉN DEBERÁ DETERMINAR LAS MEDIDAS CORRECTIVAS URGENTES Y PRECISAR SI EL INMUEBLE PUEDE CONTINUAR OCUPADO DE MANERA SEGURA, INFORMANDO EL RESULTADO A ESTE CONGRESO.', 'APROBADA', '2026-08-14', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7139822920162453.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.6535517150402488.pdf"]', NULL, 'CONSTRUCCIÓN Y REUBICACIÓN DE PERSONAL DE LA JURISDICCIÓN SANITARIA NO.1 MEXICALI', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('76', NULL, '2026-06-29', '2026-07-02', '“ÚNICO. EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A DIANA ASUNCIÓN PÉREZ ÁLVAREZ, DIRECTORA GENERAL DEL SISTEMA PARA EL DESARROLLO INTEGRAL DE LA FAMILIA EN ESTE ESTADO; A JOSÉ ADRIÁN MEDINA AMARILLAS, SECRETARIO DE SALUD EN ESTE ESTADO; Y AL TITULAR DE LA SECRETARÍA DEL BIENESTAR EN ESTE ESTADO, PARA QUE EN EL ÁMBITO DE SUS COMPETENCIAS Y ATRIBUCIONES, ATIENDAN Y VISIBILICEN LA ACONDROPLASIA COMO UNA CONDICIÓN GENÉTICA DE DISCAPACIDAD MOTRIZ Y GARANTICEN QUE LAS PERSONAS QUE LA VIVEN, ACCEDAN A LOS DERECHOS Y SERVICIOS QUE LA LEY PARA LAS PERSONAS CON DISCAPACIDAD EN EL ESTADO DE BAJA CALIFORNIA YA LES RECONOCE”', 'APROBADA', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.3391639001761346.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.8704469779308257.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.34821315645070217.pdf","https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/0.7174672229251046.pdf"]', 'QUE SE ATIENDAN Y VISIBILICEN LA ACONDROPLASIA COMO UNA CONDICIÓN GENÉTICA DE DISCAPACIDAD MOTRIZ Y GARANTICEN QUE LAS PERSONAS QUE LA VIVEN, ACCEDAN A LOS DERECHOS Y SERVICIOS QUE LA LEY PARA LAS PERSONAS CON DISCAPACIDAD EN EL ESTADO DE BAJA CALIFORNIA YA LES RECONOCE.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('80', NULL, '2026-08-25', '2026-08-27', 'ÚNICO: EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A SECRETARIO GENERAL DE GOBIERNO, JUAN JOSÉ PON MÉNDEZ, ASÍ COMO A NORMA ALICIA BUSTAMANTE MARTÍNEZ, PRESIDENTA MUNICIPAL DE MEXICALI, BAJA CALIFORNIA; ROMÁN COTA MUÑOZ, PRESIDENTE MUNICIPAL DE TECATE, BAJA CALIFORNIA; ABDIEL GUTIÉRREZ CORONADO, PRESIDENTE MUNICIPAL DE TIJUANA, BAJA CALIFORNIA; MARÍA DEL ROCÍO ADAME MUÑOZ, PRESIDENTA MUNICIPAL DE PLAYAS DE ROSARITO, BAJA CALIFORNIA; CLAUDIA JOSEFINA AGATÓN MUÑIZ, PRESIDENTA MUNICIPAL DE ENSENADA, BAJA CALIFORNIA; MIRIAM ELIZABETH CANO NÚÑEZ, PRESIDENTA MUNICIPAL DE SAN QUINTIN, BAJA CALIFORNIA  Y A JOSÉ LUIS DAGNINO LÓPEZ, PRESIDENTE MUNICIPAL DE SAN FELIPE, BAJA CALIFORNIA, EN VIRTUD DEL ENDEUDADO INTERÉS PÚBLICO, RELATIVO A LA SEGURIDAD CIUDADANA EN CASO DE EVENTOS NATURALES TRÁGICOS DERIVADOS DE DESASTRES NATURALES.”', 'APROBADA', '2026-09-01', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/1788823325479-f74qzdryp4e.pdf"]', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/1788823323531-diftlduqcaj.pdf"]', NULL, 'PLANEAR Y EJECUTAR PROYECTOS DE SEGURIDAD CIUDADANA EN CASO DE DESASTRES NATURALES DENTRO DEL ESTADO DE BAJA CALIFORNIA.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('81', NULL, '2026-09-07', '2026-09-10', '“ÚNICO: EL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA EXHORTA RESPETUOSAMENTE A LAS PERSONAS TITULARES DE LAS PRESIDENCIAS MUNICIPALES DE LOS SIETE AYUNTAMIENTOS DEL ESTADO DE BAJA CALIFORNIA, PARA QUE FORTALEZCAN LA AUTORIZACIÓN, SUPERVISIÓN, VIGILANCIA Y RECEPCIÓN DE LAS OBRAS QUE INTERVENGAN LA VÍA PÚBLICA, Y GARANTICEN QUE LAS EMPRESAS PARTICULARES, CONCESIONARIAS, PRESTADORAS DE SERVICIOS, CONTRATISTAS Y ENTIDADES PÚBLICAS RESPONSABLES RESTITUYAN DEBIDAMENTE EL PAVIMENTO, BANQUETAS Y DEMÁS INFRAESTRUCTURA URBANA QUE SEA AFECTADA.” Y QUE ESTO SE REALICE BAJO LOS SIGUIENTES PUNTOS:  PRIMERO. QUE LAS PERSONAS TITULARES DE LAS PRESIDENCIAS MUNICIPALES DE MEXICALI, NORMA ALICIA BUSTAMANTE MARTÍNEZ; TIJUANA, ABDIEL GUTIÉRREZ CORONADO; ENSENADA, CLAUDIA JOSEFINA AGATÓN MUNÍZ; TECATE, ROMÁN COTA MUÑOZ; PLAYAS DE ROSARITO, MARÍA DEL ROCÍO ADAME MUÑOZ; SAN QUINTÍN, MIRIAM ELIZABETH CANO NÚÑEZ, Y SAN FELIPE, JOSÉ LUIS DAGNINO LÓPEZ, PARA QUE INSTRUYAN A LAS DEPENDENCIAS, DIRECCIONES Y UNIDADES ADMINISTRATIVAS COMPETENTES A FORTALECER LOS MECANISMOS DE AUTORIZACIÓN, SUPERVISIÓN, INSPECCIÓN Y RECEPCIÓN DE TODA OBRA QUE IMPLIQUE LA INTERVENCIÓN O AFECTACIÓN DE LA VÍA PÚBLICA. SEGUNDO. PARA QUE DENTRO DE SUS ATRIBUCIONES, ESTABLEZCAN EN LOS PERMISOS Y AUTORIZACIONES CORRESPONDIENTES LA OBLIGACIÓN EXPRESA DE QUE LAS EMPRESAS PARTICULARES, CONCESIONARIAS, PRESTADORAS DE SERVICIOS, CONTRATISTAS, ORGANISMOS PÚBLICOS Y DEMÁS RESPONSABLES DE LAS OBRAS REPAREN Y RESTITUYAN INTEGRALMENTE EL PAVIMENTO, BANQUETAS, GUARNICIONES, CAMELLONES, RAMPAS, CICLOVÍAS, ÁREAS PEATONALES Y DEMÁS INFRAESTRUCTURA URBANA QUE RESULTE AFECTADA, PROCURANDO QUE ÉSTA QUEDE EN CONDICIONES EQUIVALENTES O SUPERIORES A LAS QUE PRESENTABA ANTES DE LA INTERVENCIÓN Y CONFORME A LAS ESPECIFICACIONES TÉCNICAS APLICABLES. TERCERO. QUE LA SUPERVISIÓN MUNICIPAL SE REALICE DURANTE LA EJECUCIÓN DE LOS TRABAJOS Y, PARTICULARMENTE, MEDIANTE UNA INSPECCIÓN FINAL PREVIA A LA CONCLUSIÓN O RECEPCIÓN DE LA OBRA, A EFECTO DE VERIFICAR QUE LA REPARACIÓN HAYA SIDO REALIZADA CORRECTAMENTE, QUE NO EXISTAN RIESGOS PARA LA POBLACIÓN Y QUE LA INFRAESTRUCTURA PÚBLICA HAYA RECUPERADO SUS CONDICIONES DE SEGURIDAD, FUNCIONALIDAD Y ACCESIBILIDAD. CUARTO. PARA QUE, ANTE EL INCUMPLIMIENTO DE LAS CONDICIONES ESTABLECIDAS EN LOS PERMISOS O AUTORIZACIONES, SE APLIQUEN DE MANERA EFECTIVA LAS MULTAS, REQUERIMIENTOS, MEDIDAS DE SEGURIDAD, SUSPENSIONES Y DEMÁS SANCIONES ADMINISTRATIVAS PREVISTAS EN LA LEGISLACIÓN Y REGLAMENTACIÓN APLICABLES, GARANTIZANDO EN TODO MOMENTO EL DEBIDO PROCESO Y EL DERECHO DE AUDIENCIA. QUINTO. PARA QUE, TRATÁNDOSE DE EMPRESAS, PERSONAS FÍSICAS O MORALES QUE REINCIDAN EN TRABAJOS DEFICIENTES O EN EL INCUMPLIMIENTO DE SUS OBLIGACIONES DE REPARACIÓN, SE CONSIDEREN DICHOS ANTECEDENTES PARA LA PROCEDENCIA DE FUTURAS AUTORIZACIONES, PERMISOS O RENOVACIONES, PUDIENDO CONDICIONARSE, SUSPENDERSE O NEGARSE ÉSTOS CUANDO LEGALMENTE RESULTE PROCEDENTE.', '', '', '', '', '', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/1788898234536-5p0z9rx6btt.pdf"]', NULL, NULL, 'MANTENER EN PERFECTAS CONDICIONES LAS VIALIDADES Y DEMÁS ZONAS PÚBLICAS, TODO ELLO POSTERIOR A LA TERMINACIÓN DE TRABAJOS POR EMPRESAS PARTICULARES Y/O GUBERNAMENTALES QUE LASTIMEN ESOS LUGARES PÚBLICOS CON LA REALIZACIÓN DE SUS TRABAJOS.', '');
INSERT INTO proposiciones (id, no, fecha_ingreso_procepar, fecha_pleno, proposicion, resultado_votacion, fecha_acuse_recibido_autoridad, fecha_respuesta_autoridad, anotaciones, tipo, pdf_foto, acuerdo, respuesta_acuerdo, objetivo, turnado_comision) VALUES ('82', NULL, '2026-09-07', '2026-09-10', 'ÚNICO.- LA XXV LEGISLATURA DEL H. CONGRESO DEL ESTADO DE BAJA CALIFORNIA, EXHORTA RESPETUOSAMENTE AL H. AYUNTAMIENTO DE MEXICALI Y A NORMA ALICIA BUSTAMANTE MARTÍNEZ, PRESIDENTA MUNICIPAL DE MEXICALI, ASÍ COMO A ROGER SOSA ALAFFITA, TESORERO MUNICIPAL DE MEXICALI, Y A RUBÉN DARÍO OSUNA BELTRÁN, DIRECTOR DEL H. CUERPO DE BOMBEROS DE MEXICALI, PARA QUE, EN EL ÁMBITO DE SUS RESPECTIVAS COMPETENCIAS Y CONFORME A LA DISPONIBILIDAD DE LOS RECURSOS DEL ERARIO MUNICIPAL, SE DESTINEN DE MANERA PRIORITARIA LAS PARTIDAS PRESUPUESTALES NECESARIAS PARA LA ADQUISICIÓN, REPOSICIÓN Y MANTENIMIENTO DEL PARQUE VEHICULAR DE AMBULANCIAS Y UNIDADES DE EMERGENCIA, ASÍ COMO PARA LA DOTACIÓN SUFICIENTE DE EQUIPO DE PROTECCIÓN PERSONAL, HERRAMIENTAS Y PERSONAL OPERATIVO DEL H. CUERPO DE BOMBEROS DE MEXICALI, CON EL FIN DE GARANTIZAR UNA ATENCIÓN OPORTUNA, SEGURA Y EFICIENTE DE LAS EMERGENCIAS QUE SE PRESENTEN EN LA CIUDAD Y EN EL VALLE DE MEXICALI.', '', '', '', '', 'PROPOSICION', '["https://ehsbhaepkknxdpvcttaz.supabase.co/storage/v1/object/public/attachments/proposiciones/1788899171785-ytb1r3f05eq.pdf"]', NULL, NULL, 'QUE EL CUERPO DE BOMBEROS DE ESTE MUNICIPIO, CUENTE CON EQUIPO SUFICIENTE Y EN BUEN ESTADO PARA LA REALIZACIÓN DE LAS ACTIVIDADES PROPIAS DE LA INSTITUCIÓN', '');
